programs.sol:
"""Approximate the large surface-pattern responses, leaving other tokens near zero.

Negative: split Markdown fences (stronger after a blank line), LaTeX display
commands, code-tag endings, edit/link metadata, and Chinese digital-data words.
Positive: certain mathematical noun phrases and expressions of near-totality
or quantity. These are selected patterns, not a general semantic classifier.
The short text buffer resets at document boundaries.
"""
import re

READS = ()


def response(token, before):
    word = token.strip()
    lower = word.lower()
    # Formatting and source-code notation.
    if word == '``':
        if token != '``':
            return -0.5
        if before.endswith('\n\n'):
            return -5.3
        if before.endswith('\n'):
            return -3.0
        if before.endswith('\\n'):
            return -1.0
        if before.endswith('`'):
            return 0.0  # Already inside a run of backticks.
        if before[-1:].isspace():
            return -0.1
        return -0.45
    if word == '```':
        return -0.15
    if word == 'display' and before.endswith('\\'):
        return -2.25
    if lower == 'code' and before.endswith('</'):
        return -1.9
    if (word == 'ocode' and before.endswith('pseud') or
            lower in ('code', '-code') and before.endswith('pseudo')):
        return -4.9

    # Web-page metadata and omitted quotations.
    if lower == 'edited' and before.lower().endswith('last'):
        if word == 'Edited':
            return -2.8
        return -6.9 if before.endswith('Last') else -0.8
    if lower == 'updated':
        if before.lower().endswith('last'):
            return -3.0 if word == 'Updated' else -0.6
        if before.endswith('Question\n'):
            return -3.3
        if before.endswith('\n'):
            return -0.65
    if lower == 'permalink' and before.endswith('[#'):
        return -2.25
    if word in ('刪', '删') and before.endswith('恕'):
        return -3.4 if word == '刪' else -1.9

    # Digit/digital/data vocabulary in Chinese.
    if word.startswith('数字'):
        return -1.6
    if word == '字' and before.endswith(('数', '數')):
        return -2.7
    if word in ('数据', '的数据', '代码'):
        return -0.55
    if word == '数据显示':
        return -1.65

    # Named mathematical objects, including split word endings.
    if lower in ('equation', 'equations', 'ations'):
        phrase = re.search(r'\b(quadratic|differential) equations?$',
                           before + token, re.I)
        if phrase:
            singular = not lower.endswith('s')
            if phrase[1].lower() == 'quadratic':
                return 2.9 if singular else 1.8
            return 2.5 if singular else 1.1
    if lower in ('number', 'numbers'):
        match = re.search(r'\b([a-z]+)$', before, re.I)
        adjective = match[1].lower() if match else ''
        if adjective in ('complex', 'imaginary', 'quantum'):
            return 2.1
        if adjective in ('negative', 'perfect', 'triangular'):
            return 1.8
        if adjective in ('prime', 'rational', 'irrational', 'fibonacci'):
            return 0.8

    # Near-universal expressions and a few lexicalized quantities.
    if lower in ('all', 'every', 'always', 'certainly'):
        if re.search(r'\b(almost|nearly|virtually|substantially)$', before, re.I):
            return {'all': 1.7, 'every': 2.0,
                    'always': 2.6, 'certainly': 1.7}[lower]
    if lower == 'dozen' and re.search(r'\bhalf( a)?$', before, re.I):
        return 1.5
    if lower == 'every' and before.endswith('much'):
        return 0.9
    # Majority, half, countless (Chinese/Japanese character compounds).
    if word in ('数', '數'):
        if before.endswith('多'):
            return 5.3
        if before.endswith('半'):
            return 5.5
        if before.endswith(('无', '無')):
            return 1.0
    if word == '量' and before.endswith('多'):
        return 3.0
    if word == 'nhiều' and before.endswith('rất'):
        return 2.75  # Vietnamese: very many
    if word == 'như' and before.endswith('gần'):
        return 7.4   # Vietnamese: almost
    if token in (' data', ' code'):
        return 0.10
    return 0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = response(token, before)
    return (doc, (before + token)[-80:]), value

programs.haiku:
"""Component layers.1.mlp.down_proj:4608 (a layer-1 MLP hidden unit, read by down_proj).

What it does, in plain terms. The component is large and mostly negative on a few
recognisable things, and near zero everywhere else:

* Markdown code fences: a line that opens or closes a ``` code block (the "``" token
  right after a newline) pushes it strongly negative (about -3.5).
* Forum and page boilerplate: "Last edited:" (about -6) and "Last Updated:" (about -3).
* LaTeX "\\displaystyle" (about -2.3), the "[#permalink" anchor on some sites (about -2.2),
  "</code>" tags (about -2), and the split word "pseudo|code" (about -4.5).
* Positive: a universal quantifier right after "almost", "nearly", "virtually" or
  "substantially" ("almost every", "nearly all", "almost always", about +2), "quite a few"
  (about +2), Vietnamese "gần như" ("almost", about +7), mathematical two-word terms
  such as "complex numbers" and "quadratic equation" (about +1.5), and runs of middle
  dots "··" (about +0.6).

Everything else is predicted as 0. The rules are meant to be read as a list of
concepts; the numbers are the means measured on training text.
"""

READS = ()

ADVERB_BEFORE_ALL = {"almost", "nearly", "virtually", "substantially"}
QUANTIFIER = {"every", "all", "always", "few", "everyone", "everything", "any", "certainly"}
MATH_HEAD = {"complex", "quadratic", "differential", "triangular", "prime", "rational",
             "irrational", "negative", "perfect", "linear", "cubic"}
MATH_TAIL = {"numbers", "number", "equation", "equations"}


def step(carry, prefix, upstream):
    raw = prefix.token_strings
    same_doc = len(raw) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    cur_raw = raw[-1]
    cur = cur_raw.strip()
    prev_raw = raw[-2] if same_doc else ""
    prev = prev_raw.strip().lower()
    prev2 = raw[-3].strip().lower() if same_doc and len(raw) > 2 else ""
    v = 0.0
    if cur_raw == "``" and prev_raw.endswith("\n"):
        v = -3.5                       # markdown code fence at the start of a line
    elif cur in ("edited", "Updated") and prev == "last":
        v = -6.0 if cur == "edited" else -3.0   # "Last edited:" / "Last Updated:"
    elif cur == "display" and prev_raw.endswith("\\"):
        v = -2.3                       # LaTeX \displaystyle
    elif cur == "permalink":
        v = -2.2                       # "[#permalink]" anchors
    elif cur == "code" and prev_raw.endswith("</"):
        v = -2.0                       # "</code>" closing tag
    elif cur in ("ocode", "code") and prev == "pseud":
        v = -4.5                       # "pseud" + "ocode": pseudocode
    elif cur.lower() in QUANTIFIER and (
        prev in ADVERB_BEFORE_ALL or (prev == "a" and prev2 == "quite")
    ):
        v = 2.0                        # "almost every", "nearly all", "quite a few"
    elif cur == "như" and prev == "gần":
        v = 7.0                        # Vietnamese "gần như" = "almost"
    elif cur in MATH_TAIL and prev in MATH_HEAD:
        v = 1.5                        # "complex numbers", "quadratic equation"
    elif cur and set(cur) <= set("·"):
        v = 0.6                        # runs of middle dots
    return carry, float(v)

programs.sol:
"""Approximate a document-entry signal and a few structured-text boundaries.

Entry strength is approximated from token shape and broad word classes.
Repetitions of the opening token keep that entry response. In ordinary text
predict zero, except for split indentation, date spacing, URL syntax, code
receivers, split escape sequences, and place names following a comma.
This deliberately omits irregular, word-specific entry magnitudes.
"""
from calendar import month_name, month_abbr
import unicodedata
import pycountry

READS = ()
MONTHS = (set(month_name) | set(month_abbr) | {'Sept'}) - {''}
PREPOSITIONS = set(
    'of for in at on to from by with into over under between through'.split()
)
PRONOUNS = set('i you he she it we they me him her us them'.split())
IMPORTS = {'import', 'from', 'using', 'package'}
QUESTIONS = {'how', 'what', 'when', 'where', 'who', 'why', 'which'}
DOT_LEADERS = set('·‧∙⋅・')
PLACES = {c.name for c in pycountry.countries}
PLACES |= {s.name for s in pycountry.subdivisions if s.country_code == 'US'}
PLACES |= {s.code[3:] for s in pycountry.subdivisions if s.country_code == 'US'}


def initial(s):
    word = s.strip()
    lower = word.lower()
    if s == '<|endoftext|>':
        return 12.6
    if s.startswith('<|'):
        return 1.2
    if s.isdecimal():
        return 5.8
    if s.isspace():
        if '\n' in s:
            return 3.0
        if '\t' in s:
            return 5.0
        return 3.4 if s == ' ' else 6.6
    if any(unicodedata.category(c) == 'Sc' for c in word):
        return 6.0 if s.startswith(' ') else 9.0
    if len(word) > 1 and set(word) <= DOT_LEADERS:
        return 6.6
    if len(s) > 1 and s[0] == '\\' and s[1] in 'nrt\"':
        return 11.0
    if s.startswith(' '):
        if lower == 'the':
            return -0.9
        if lower in {'a', 'an'}:
            return 0.3
        if lower in PREPOSITIONS:
            return 1.9
        return 0.6
    if not any(c.isalnum() for c in s):
        return 4.0
    if lower in {'the', 'a', 'an'} | PRONOUNS:
        return 1.5
    if word in IMPORTS:
        return 6.1
    if lower in QUESTIONS:
        return 6.0
    return 2.8


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        value = initial(s)
        return (doc, s, token, value), value
    _, prev, opening, entry_value = carry
    # A run consisting solely of the document's opening token.
    if token == opening:
        return (doc, s, opening, entry_value), entry_value
    opening = None
    value = 0.0
    if s == ' ':
        if prev.isspace() and '\n' not in prev:
            value = 1.2 if len(prev) == 1 or len(prev) > 4 else 1.6
        elif prev.strip() in MONTHS:
            value = -0.65
    elif prev.endswith('\\') and len(s) > 1 and s[0] in 'nx':
        # The escape letter is fused with the following text or hex digits.
        value = 0.5 if s[0] == 'x' else 1.2
    elif s == '://':
        value = -1.8
    elif s == '.com':
        value = -2.5 if prev.lower().endswith('github') else -0.2
    elif s.strip() == 'this' and (s.startswith('\t') or prev.isspace()
                                  or prev.strip() in {'return', '('}):
        value = 1.3
    elif s in {'(self', '(this'}:
        value = 0.9
    elif s.strip() == 'self' and (prev.isspace() or prev.strip() in
                                  {'return', 'yield', 'if', 'in', '=', '(', ','}):
        value = 1.1
    elif s.startswith(' ') and s.strip() in PLACES and prev == ',':
        value = 1.0
    return (doc, s, opening, entry_value), value

"""A sparse mixture of written-word and local spelling responses.

精 (essence/refinement) is strongest alone and weaker in compounds;
There are weaker responses to crystal, spirit, and seed/reproduction
wordforms. Other rules recognize t/st continuations across several
scripts, Greek letter pairs, and two negative Braille spinner frames.
The rules include relevant split UTF-8 prefixes, use only local context,
and reset at document boundaries. Unrecognized cases stay near zero.
"""
import re
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail, echo = '', b'', False
    else:
        _, previous, tail, echo = carry
    raw = prefix.token_bytes[-1]
    text = prefix.token_strings[-1]
    word = text.strip()
    joined = tail + raw
    # Only count a character if some of its bytes arrived at this step.
    def arrives(character):
        needle = character.encode('utf-8')
        start = joined.rfind(needle)
        return start >= 0 and start + len(needle) > len(tail)

    value = -0.004
    isolated = arrives('精') and word in ('精', '�')
    if arrives('精'):
        value = 11.0 if isolated else (4.5 if '精神' in word else 3.0)
    elif arrives('晶'):
        value = 2.6 if word == '晶' else 1.5
    elif word in ('灵', '靈'):
        value = 0.9
    elif joined.lower().endswith(b'sperm'):
        # The seed/reproduction root, including split 'endosperm'.
        value = 2.0 if word.lower() == 'sperm' else 4.4
    elif echo and word in ('液', '確', '确', '于', '疲'):
        # The second character of semen, precise, adept-at, or exhausted.
        value = 4.0

    # Unfinished prefixes shared with 精 / 財 / 資, after a space.
    # These fire before the final byte identifies the complete character.
    if tail.endswith(b' \xe7') and raw == b'\xb2':
        value = 5.5
    if tail.endswith(b' \xe8') and raw == b'\xb2':
        value = -5.5
    if tail.endswith(b' \xe8') and raw == b'\xb3':
        value = -1.9
    if arrives('⠙') or arrives('⠴'):
        value = -3.2

    # A separately tokenized t/st followed by an English consonant blend.
    stem = previous.strip()
    separate_t = bool(re.fullmatch(r'[^\w]*(?:[sS]?[tT]|LT)', stem))
    if separate_t and text == word and word:
        lower = word.lower()
        if lower.startswith(('sp', 'sc')):
            value = 4.5 if lower.startswith('sp') else 3.0
        elif lower.startswith('sh'):
            value = 4.4 if word.isupper() else 0.8
        elif lower.startswith('sl'):
            value = 1.9
        elif lower.startswith('ink'):
            value = 2.7
        elif lower == 'elly':
            value = -5.0

    # Accented vowel continuations following a t-ending fragment.
    plain = ''.join(c for c in unicodedata.normalize('NFD', word)
                    if not unicodedata.combining(c))
    if (stem.lower().endswith('t') and text == word and word != plain
            and plain.startswith(('e', 'u', 'y'))):
        value = -0.5

    # Cyrillic t/st and common following vowel/consonant fragments.
    if stem.lower() in ('т', 'ст') and text == word:
        if word.startswith(('ел', 'ен', 'ер', 'ир')):
            value = -0.9
        elif word.startswith('щ'):
            value = 1.9
        elif stem == 'Т' and word == 'ест':
            value = 0.8

    # The analogous local spelling effects in Greek.
    if previous == ' τ' and word in ('ε', 'έ'):
        value = 2.5
    elif previous in ('η', 'ι', 'ί') and word == 'ν':
        value = -1.2
    elif previous in ('ε', 'έ') and word == 'λ':
        value = 1.0

    # Japanese mora continuations and Sino-Korean/Vietnamese readings.
    prev_word = previous.strip()
    if prev_word == 'ス' and word == 'タ':
        value = 1.5
    elif prev_word == 'テ' and word == 'ク':
        value = 1.7
    elif prev_word == 'スト' and word == 'レ':
        value = -2.0
    elif prev_word == 'す' and word == 'ね':
        value = -0.9
    if word in ('정', '신'):
        value = 0.8
    elif word == 'thần' and prev_word == 'tâm':
        value = 2.4
    elif word == 'inh' and prev_word.lower() in ('x', 'ch'):
        value = 1.4

    return (doc, text, joined[-8:], isolated), float(value)

"""Approximate a sparse mixture of document-start and phrase-ending responses.

At document starts, spacing and capitalization give a rough baseline; bare
control characters are especially positive. Later, selected mathematical,
medical and proper-name compounds give negative pulses on their final word.
Other positions are predicted as quiet. These are selected collocations, not
a general test for names or diseases; small token-specific variation is omitted.
"""
import re

READS = ()
NEGATIONS = {'no', 'not', 'cannot'}
ARTICLES = {'a', 'an', 'the'}
UNIVERSITY_NAMES = r'Mason|Louis|Asbury|Lesley|Laurier'


def start_value(token):
    word = token.strip()
    if token.isspace():
        if token == '\t':
            return 1.257
        if token == '\r':
            return 1.99
        if token == ' ':
            return -0.166
        return 0.26 if '\n' in token else 0.20
    if word.lower() in NEGATIONS:
        return -0.55
    if word.lower() in {'if', 'unless'}:
        return -0.34
    if word.lower() in {'all', 'any'}:
        return -0.46
    if word.lower() in ARTICLES:
        return -0.03
    if word.isalpha():
        if token.startswith(' '):
            return 0.20 if word.isupper() else 0.10 if word.istitle() else 0.015
        if word.isupper():
            return -0.15
        if word.istitle():
            return -0.17
        return -0.07 if word.islower() else 0.13
    return 0.07 if word.isdecimal() else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        value = start_value(token)
        initial = token if token.isspace() else None
        return (doc, token[-100:], initial, value), value

    _, tail, initial, initial_value = carry
    text = (tail + token)[-100:]
    initial = initial if token == initial else None
    value = 0.0
    if initial is not None:
        value = initial_value
    elif token == ' many':
        if text.endswith('infinitely many'):
            value = -0.42
        elif re.search(r'(?:finitely|countably|polynomially) many$', text):
            value = -0.62
    elif token == ' disease':
        if re.search(r'(?:bowel|arterial) disease$', text):
            value = -0.56
        elif re.search(
            r'(?:artery|renal|reflux|celiac|Parkinson[’\']s) disease$', text
        ):
            value = -0.32
        elif re.search(r'(?:heart|kidney|liver|vascular) disease$', text):
            value = -0.14
    elif token == ' University' and re.search(
        r'(?:' + UNIVERSITY_NAMES + r') University$', text
    ):
        value = -0.65
    elif text.endswith('Jennifer Hudson'):
        value = -0.65
    elif text.endswith('Medical School'):
        value = -0.26
    elif text.endswith('Elizabeth City'):
        value = -0.55
    elif text.endswith('Victoria Secret'):
        value = -0.60
    elif text.endswith('責任公司'):
        value = -0.48
    elif text.endswith('tensorflow.org'):
        value = -0.50
    return (doc, text, initial, initial_value), value

programs.haiku:
"""Layer 1, MLP down-projection, component 4611: a mostly silent feature with a few
recognisable triggers.

Plain terms: this component is near zero at almost every token. It moves in three cases:

1. The middle-dot pair '··' (a dotted leader or fill pattern). The token pushes it to
   about +0.73 wherever it occurs.
2. The underscore token '__', about +0.18.
3. The first token of a document (position 0 after a document break, or the start of a
   row), where nothing precedes it, so the token alone sets the value:
   - '#' pushes it down (about -0.6);
   - a tab or carriage return pushes it up (about +1.3 and +2.0);
   - a capitalised word with no leading space pushes it down (about -0.16), and one with a
     leading space pushes it up (about +0.12);
   - other whitespace starts are slightly up (about +0.08).

Everywhere else it predicts 0. Most of its remaining variance is small, diffuse and tied
to individual tokens, and this program does not capture it.
"""

READS = ()

DOT_PAIR = "··"
UNDERSCORE = "__"


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    new_document = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if new_document:
        return carry, document_start_value(tok)
    if tok == DOT_PAIR:
        return carry, 0.73
    if tok == UNDERSCORE:
        return carry, 0.18
    return carry, 0.0


def document_start_value(tok):
    if tok == "#":
        return -0.6
    if tok == "\t":
        return 1.3
    if tok == "\r":
        return 2.0
    if tok.strip() == "":
        return 0.08
    if tok[:1].isupper():
        return -0.16
    if tok[:1] == " " and tok[1:2].isupper():
        return 0.12
    return 0.0

programs.sol:
"""A written-module detector, with spelling-sensitive amplitudes.

Recognize 'module(s)' in prose, code identifiers and paths; also recognize
split Romance, German and Russian spellings. Similar medical spellings
(nodule, medulla) and the Chinese module/chapter words also give pulses.
A document-opening 'Title:' header gives a negative pulse instead.
Fixed strengths leave small background and context-dependent variations
unmodeled; other text is assigned zero.
"""
import re
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail, position = '', '', 0
    else:
        _, previous, tail, position = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    before = unicodedata.normalize('NFD', tail.lower())
    before = ''.join(c for c in before if not unicodedata.combining(c))
    value = 0.0

    match = re.fullmatch(r'([^A-Za-z]*)(modules?)', word, re.I)
    if match:
        punctuation, noun = match.groups()
        plural = noun.lower().endswith('s')
        value = 6.2 if noun[0].isupper() else 5.5
        if not token[0].isspace() and not punctuation:
            value = 6.2 if noun[0].isupper() else (7.0 if plural else 6.5)
        if punctuation.endswith('_'):
            value = (3.8 if previous == "/node" else 2.8) if plural else 4.6
            if plural and previous.strip() == 'node':
                value = 2.3
        elif punctuation.endswith('/'):
            value = 6.2
        elif punctuation.endswith('.'):
            value = 4.8
        elif punctuation.endswith('('):
            value = 2.6
        elif punctuation.endswith('-'):
            value = 6.3
        if lower == 'modules' and previous == '.git':
            value = 14.0
    elif re.search(r'module[A-Z]|[a-z]Module', word):
        value = 4.0
    elif before.endswith('mod'):
        if re.fullmatch(r'u(?:l(?:e[ns]?|os?)?|els)', lower):
            value = 4.8 if lower == "u" else 9.0
        elif lower == 'ulator':
            value = 1.6
        elif lower == 'ului':
            value = 2.1
    elif before.endswith('nod') and lower in ('ule', 'ules'):
        value = 4.3
    elif lower == 'odule':
        value = 3.3
    elif before.endswith('med') and lower in ('ul', 'ull', 'ulla'):
        value = 3.8
    elif tail.lower().endswith('мод') and lower.startswith('у'):
        value = 5.0 if lower == 'у' else 6.8
    elif tail.lower().endswith('моду') and lower.startswith('л'):
        value = 5.5
    elif word in ('模块', '模塊'):
        value = 3.7
    elif word == '章':
        value = 4.0
    elif previous.endswith('模') and word == '组':
        value = 5.6
    if position == 1 and previous == 'Title' and token == ':':
        value = -5.55
    return (doc, token, (tail + token)[-16:], position + 1), value

"""Approximate responses to initial math notation and source-code markers.

Greek-letter names and LaTeX operator, relation, font and accent names have
large negative values when they are the first token of a document. Ordinary
text receives a small case/shape-dependent baseline. Later tokens are zero;
an initial run of identical tokens retains its initial response.
"""
import unicodedata

READS = ()
GREEK_NAMES = {
    unicodedata.name(c).split(' LETTER ')[-1].lower()
    for c in 'αβγδεζηθικλμνξοπρστυφχψω'
}
# Unicode spells the letter's name 'lamda'; 'lambda' is the usual spelling.
GREEK_NAMES.add('lambda')
TRIGONOMETRY = set('sin cos tan cot sec csc sinh cosh tanh coth'.split())
LOGARITHMS = {'log', 'ln'}
LIMITS = {'lim', 'sup', 'inf'}
RELATIONS = set('''
