    'you', 'he', 'she', 'it', 'they', 'him', 'her', 'them',
    'your', 'his', 'its', 'their', 'this', 'that', 'these', 'those',
}
FIRST_PERSON = {'i', 'me', 'my', 'we', 'us', 'our'}
AUXILIARIES = {
    'am', 'is', 'are', 'was', 'were', 'be', 'been', 'being', 'do',
    'does', 'did', 'have', 'has', 'had', 'can', 'could', 'will',
    'would', 'shall', 'should', 'may', 'might', 'must',
}
