        return 1.3
    if w.isdecimal():
        return 3.0
    if word in {'the', 'a', 'an'}:
        return (5.2 if word == 'the' else 3.0) - 1.5 * spaced
    if word in {'of', 'to'}:
        return 5.9
    if word in PREPOSITIONS:
        return 4.7
    if word in RELATIONS:
        return 2.8
    if word == 'not':
        return 6.5
    if word in {'no', 'never', 'none', 'neither', 'nor'}:
        return 0.5
    if word in FIRST_PERSON:
        return 3.2
    if word in PRONOUNS or word in AUXILIARIES:
        return 1.5
    if word in {'and', 'or', 'but'}:
        return 3.3
    if word in SUBORDINATORS:
        return 1.8
    if w == 'package':
        return 12.8
    if w in {'import', 'using'}:
        return 8.4
    if w in DECLARATIONS:
        return 6.5
