    name = unicodedata.name(first, '')
    script = next((s for s in A_N_STRENGTH if s in name), '')
    return anyascii(text.translate(ALEFS)).lower(), script


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        prev, before, earlier, pending = '', '', '', b''
    else:
        _, prev, before, earlier, pending = carry
    raw = pending + prefix.token_bytes[-1]
    token, used = codecs.utf_8_decode(raw, 'ignore', False)
    pending = raw[used:]
    if not token:
        return (doc, prev, before, earlier, pending), 0.0

    p, script = spelling(prev)
    t, current_script = spelling(token)
    b, _ = spelling(before)
    e, _ = spelling(earlier)
    p = p.strip()
    value = 0.0
    if p and t:
        bare_n = t.strip(' ([{') in ('n', 'nd')
        if p.endswith('a') and (t.startswith('n') or bare_n):
            value -= A_N_STRENGTH.get(script, 0.0) / len(p)
            initial = prev[0].isspace() or prev[0].isupper()
            initial = initial or before.endswith((' ', '\n'))
            if len(p) == 1 and initial:
                if script in ('CYRILLIC', 'GREEK'):
                    value -= 0.82

        if t[0].isalpha():
            if p.endswith('an') and script in ('LATIN', 'CYRILLIC', 'ARABIC'):
                pulse = -0.15
                if t.startswith('an'):
                    pulse += 0.74
                elif t.startswith('n'):
                    pulse += 0.13
                elif t.startswith(('c', 't')):
                    pulse += 0.29
                elif t[0] in 'aeiou':
                    pulse -= 0.12
                value += pulse / max(1, len(p) - 1) ** 1.1
            if p == 'n' and b.endswith('a'):
                value -= 0.75 if script == 'GREEK' else 0.07
            if script == 'GREEK' and b.strip() == 'n' and e.endswith('a'):
                value -= 0.16
            if t.startswith('n') and p.endswith('am'):
                value += 0.67 / len(p)
            if current_script == 'GREEK' and t == 'n':
                if prev.strip().lower() in 'βγδζθκλμξπρσςτφχψ':
                    value += 1.44 + (0.83 if b.endswith('a') else 0.0)
            if (t == 'an' or t.startswith(('ana', 'ans'))):
                if p.endswith(('and', 'ant')):
                    value += 1.67 / len(p)
            if t.startswith('and') and p.endswith('in'):
                value -= 1.36 / len(p)
    return (doc, token, prev, before, pending), value

"""Surface cues for the HAVE family, with subject-sensitive English responses.

Recognize conjugations, contractions, and a few visible stems of European
HAVE verbs. Nearby dictionary word frequencies disambiguate short forms such
as French 'a', German 'hat', and Italian 'ho'. English subjects strengthen the
response, while auxiliary constructions often weaken it. This is a lexical
approximation, not a complete grammatical parser; unrelated activations are
left at zero. Keep only 200 characters of within-document context.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = ('en', 'fr', 'de', 'it', 'es', 'sv', 'nb', 'da', 'ro',
             'pt', 'nl', 'cs', 'sk', 'pl', 'hu', 'fi', 'tr')

# Conjugations of avoir, haben, avere, haber, and Scandinavian HAVE verbs.
VERBS = {
    'avoir': 1.4, 'avons': 2.4, 'avez': 1.95,
    'avait': 2.7, 'avais': 2.6, 'avaient': 2.5, 'avions': 2.4,
    'avoit': 2.1, 'avoient': 2.0,
    'aurait': 1.6, 'aurais': 1.6, 'auront': 1.6,
    'habe': 1.8, 'haben': 1.5, 'hast': 1.6,
    'hatte': 1.3, 'hatten': 1.5, 'hätte': .9, 'hätten': .9,
    'abbiamo': 2.4, 'avete': 2.0, 'hanno': 2.1,
    'aveva': 2.0, 'avevano': 1.8, 'avere': 1.4,
    'avrei': 1.8, 'avrebbe': 1.9, 'avrebbero': 1.9, 'abbiano': 1.8,
    'había': 1.8, 'habían': 1.8, 'habíamos': 1.8,
    'hemos': 2.0, 'habéis': 2.0, 'haber': .7,
    'hadde': 1.35, 'hade': 1.3, 'havde': 1.3,
}
AMBIGUOUS = {
    'fr': {'a': 1.6, 'as': 2.0, 'ai': 2.7, 'ont': 2.6},
    'it': {'ha': 2.15, 'ho': 2.4, 'ave': 1.3},
    'es': {'ha': 2.15, 'han': 2.15, 'he': 2.0},
    'de': {'hat': 1.7}, 'sc': {'har': 1.6}, 'ro': {'am': 1.6},
}
SHORT_FORMS = set().union(*(set(v) for v in AMBIGUOUS.values()))
SUBJECTS = {
    'have': {'i': 1.03, 'you': .56, 'we': .56, 'they': .56,
             'who': .77, 'that': .56, 'which': .33},
    'has': {'he': .77, 'she': .77, 'who': .77,
            'it': .25, 'that': .49, 'which': .24},
    'had': {'i': .91, 'he': .91, 'she': .91,
            'you': .55, 'we': .55, 'they': .55, 'who': .55, 'that': .55},
}
AUXILIARIES = {
    'can': -.28, 'will': -.28, 'should': -.04, 'would': -.04,
    'not': -.04, "'t": -.04, '’t': -.04,
    'do': -.04, 'does': -.04, 'did': -.04, 'to': .05,
    'may': .27, 'must': .27, 'might': .27, 'could': .27,
}
FRENCH_WORDS = set('le les la une des du et il elle ils elles nous vous '
                   'pas pour avec au aux je ce cette ces qui est on en '
                   'que comme dans un son sa ses'.split())


@lru_cache(maxsize=12000)
def word_scores(word):
    return tuple(zipf_frequency(word, lang) for lang in LANGUAGES)


def language(history):
    words = re.findall(r"[^\W\d_]+", history.lower())[-16:]
    scores = [0.0] * len(LANGUAGES)
    for word in words:
        for i, frequency in enumerate(word_scores(word)):
            scores[i] += frequency
    name = LANGUAGES[max(range(len(scores)), key=scores.__getitem__)]
    return 'sc' if name in {'sv', 'nb', 'da'} else name


def english(form, previous, history):
    p = previous.strip().strip('"“”').lower()
    if form == 'have':
        words = re.findall(r'[A-Za-z]+', history.lower())[-3:]
        # Inverted questions still contain an auxiliary: 'do I have'.
        if len(words) > 1 and words[-2] in AUXILIARIES:
            aux = words[-2]
            return -.15 if aux in {'do', 'does', 'did'} else AUXILIARIES[aux]
        if p in AUXILIARIES:
            return AUXILIARIES[p]
        if p in {'also', 'only', 'already', 'never'}:
            return -.08
    if form in SUBJECTS and p in SUBJECTS[form]:
        return SUBJECTS[form][p]
    proper = previous.strip()[:1].isupper()
    if form == 'have':
        return .60 if proper or (p.endswith('s') and p.isalpha()) else .35
    if form == 'has':
        if p == 'also':
            return -.20
        return 0.0 if p.isdigit() or not p or p == ')' else .30
    if form == 'had':
        if p in {'have', 'has', 'had', "'ve", '’ve', "'d", '’d'}:
            return 0.0
        return .65 if proper else .42
    # Participial 'having' is weaker than finite HAVE.
    if p in {',', 'after', 'for', 'at'}:
        return .20
    return -.08 if p in {'am', 'is', 'are', 'was', 'were', "'m"} else -.18


def foreign(form, token, p, history):
    lang = language(history)
    value = AMBIGUOUS.get(lang, {}).get(form, 0.0)
    if lang == 'fr':
        if token != form:
            return 0.0
        if form in {'a', 'as'}:
            words = re.findall(r"[^\W\d_]+", history.lower())[-10:]
            if not any(w in FRENCH_WORDS for w in words):
                return 0.0
        if form == 'a' and p in {'il', 'elle', 'on', "'il", '’il', "'on"}:
            value = 2.9
        elif form == 'a' and p in {'y', "'y", '’y'}:
            value = 2.0
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '')
    _, history, previous = carry
    raw = prefix.token_strings[-1]
    token = raw.strip().replace('’', "'")
    form = token.lower()
    p = previous.strip().strip('"“”').lower()
    boundary = not history or raw[:1].isspace() or not history[-1:].isalpha()
    value = 0.0
    if form == "'t" and p in {'haven', 'hasn', 'hadn'}:
        value = 1.0 if re.search(r'\bi haven$', history.lower()) else .60
    elif form == "'ve":
        value = (1.95 if '’' in raw else 1.75) if p == 'i' else 1.15
    elif form == "'d":
        value = .83 if p == 'i' else .40
    elif form == "'s":
        value = .68 if p in {'he', 'she', 'who'} else 0.0
        if p in {'that', 'let'}:
            value = .11
    elif token in {"'ai", "'a"} and p in {'j', 'n', 'l', 'm', 't', 's',
                                         'il', 'elle', 'on', 'qu', 'd'}:
        value = 2.9 if form == "'ai" else (2.6 if p == 'n' else 2.0)
    elif boundary and form in {'have', 'has', 'had', 'having'}:
        value = english(form, previous, history)
    elif boundary and form in VERBS:
        value = VERBS[form]
    elif form == 'hab':
        value = .8  # Also occurs in compounds such as German Liebhaber.
    elif boundary and form in {'av', 'abb'}:
        value = .85 if language(history) in {'fr', 'it'} else 0.0
    elif boundary and form in SHORT_FORMS:
        ordinary = (not history or raw[:1].isspace()
                    or history[-1:].isspace() or history[-1:] in {"'", '’'})
        if ordinary:
            value = foreign(form, token, p, history)
    elif not boundary and form.isalpha():
        # Recognize a conjugation completed across a token boundary.
        match = re.search(r"[^\W\d_]+$", history)
        word = ((match[0] if match else '') + form).lower()
        value = VERBS.get(word, 0.0)
    return (doc, (history + raw)[-200:], raw), value

programs.haiku:
"""Perfect-tense 'have' detector (layers.1.mlp.down_proj:4625).

The component fires on the verb "to have" when it is used as an auxiliary or main
verb right after its subject: "I have", "we've", "she has", "they had", and the same
verb in other languages ("hanno", "avait", "habe", "ont"). It is strongest after "I"
(about 1.0), weaker after other subject pronouns (about 0.6) and after other words
(about 0.35). It is switched off after modals, "to", negation, adverbs, question
auxiliaries ("do I have?"), determiners and prepositions ("the has", "in ha"), and
for have-like letters that are only pieces of a longer word. A French "a" (the verb
avoir) fires after "y", "qui", "elle", "il", "ils" ("il y a"), but not as an article.
Everything else is predicted as 0. It explains about a quarter to a third of the
variance; the rest is small, diffuse activity.
"""
READS = ()

ENGLISH = {"have", "has", "had"}
CLITIC = {"'ve", "’ve", "'ai", "’ai"}
FOREIGN = {"ha", "ho", "han", "hanno", "ont", "avait", "avons", "avez", "abbiamo", "avoir",
           "hat", "habe", "haben", "hatte", "hast", "hatten", "hadde", "hemos", "había", "har"}
FRENCH_SUBJECT = {"y", "qui", "elle", "il", "ils"}
SUBJECT = {"we", "you", "they", "he", "she", "who", "that"}
# words that make the have-verb a modal, infinitive, or question (do I have?)
BLOCK = {"will", "would", "can", "could", "should", "must", "may", "might", "shall",
         "to", "not", "n't", "'t", "’t", "do", "does", "did", "also", "only", "just", "never",
         "always", "probably", "already", "both", "each", "moreover", "still", "now", "often"}
NOUN_PHRASE = {"the", "a", "an", "of", "in", "on", "at", "for", "with", "by", "from",
               "this", "my", "your", "his", "her", "their", "our", "its", "some", "any"}
QUESTION_AUX = {"do", "does", "did", "don", "doesn", "didn", "will", "would", "can", "could"}


def word_at(prefix, back):
    """The word `back` tokens before the current one, lower-cased ('' if none)."""
    if len(prefix.token_strings) <= back:
        return ""
    return prefix.token_strings[-1 - back].strip().lower().replace("’", "'")


def step(carry, prefix, upstream):
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, 0.0
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    if word in CLITIC and not raw[:1].isspace():
        return carry, 1.6
    if not raw[:1].isspace():
        return carry, 0.0  # a piece of a longer word
    prev = word_at(prefix, 1)
    if prev in NOUN_PHRASE:
        return carry, 0.0
    if word == "a":
        return carry, 1.7 if prev in FRENCH_SUBJECT else 0.0
    if word in FOREIGN:
        return carry, 1.3
    if word not in ENGLISH or prev in BLOCK or word_at(prefix, 2) in QUESTION_AUX:
        return carry, 0.0
    if prev == "i":
        return carry, 1.0
    if prev in SUBJECT:
        return carry, 0.6
    return carry, 0.35

programs.sol:
"""Mostly a TeX delimiter-sizing detector.

Sizing commands produce large negative responses. Repeated left, right and
lowercase big commands weaken logarithmically within a document. Split command
spellings are joined, including the backslash escaping the next delimiter.
Several other TeX controls have fixed responses. Ordinary left/right/big
words are positive. Partial UTF-8 private-use characters and Latin-1 lead bytes near common
mojibake markers have smaller fixed responses. Other tokens get zero.
"""
import math
import re

READS = ()
COMMAND = re.compile(rb'\\([A-Za-z]+)(\\?)$')
SIZING = re.compile(r'[bB]igg?[lr]?$')
# Other TeX formatting controls and a logical quantifier.
TEX_CONTROLS = {
    'text': -1.1,
    'mathrm': -0.6,
    'quad': -2.0,
    'q': -1.2,                 # first token of qquad
    'qquad': -1.25,
    'large': -2.9,
    'Large': -2.9,
    'limits': -3.1,
    'l': -3.7,                 # start of langle, lVert, etc.
    'forall': 3.2,
}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        tail, counts = b'', {}
    else:
        _, tail, counts = carry
    token = prefix.token_bytes[-1]
    tail = (tail + token)[-40:]
    match = COMMAND.search(tail)
    value = 0.0
    if match:
        command = match[1].decode('ascii')
        sizing = command in ('left', 'right') or SIZING.fullmatch(command)
        if sizing and match[2]:
            if command == 'left':
                value = -10.5
            elif command == 'right':
                value = -3.3
            else:
                value = -3.5 if 'gg' in command else -4.6
        elif sizing:
            repeats = math.log1p(counts.get(command, 0))
            counts[command] = counts.get(command, 0) + 1
            if command == 'left':
                value = -15.43 + 0.99 * repeats
            elif command == 'right':
                value = -6.66 + 0.64 * repeats
            elif command.endswith('l'):
                value = -19.3
            elif command.endswith('r'):
                value = -11.6
            elif command[0] == 'B':
                value = -14.9
            else:
                value = -12.64 + 0.45 * repeats
        elif not match[2]:
            value = TEX_CONTROLS.get(command, 0.0)
            if command == 'l' and tail.endswith(b'\\left\\l'):
                value = -6.8
    else:
        word = prefix.token_strings[-1].strip().lower()
        if token == b'\xc2':
            # A separate UTF-8 lead for U+0080--00BF; larger near mojibake.
            context = tail[:-1].decode('utf-8', 'ignore')[-8:]
            broken = any(128 <= ord(c) < 160 or c in 'ÃÂ' for c in context)
            value = 1.8 if broken else 0.5
        elif token == b'\xee':
            # This UTF-8 lead byte always begins a private-use character.
            value = -1.0
        elif len(tail) >= 2 and (
            tail[-2] == 0xee and 0x80 <= tail[-1] <= 0xbf
            or tail[-2] == 0xef and 0x80 <= tail[-1] <= 0xa3
        ):
            # Two-byte prefix of a BMP private-use glyph (U+E000--F8FF).
            value = -1.2
        elif word == '∀':
            value = 1.2
        elif word == 'left':
            value = 0.65
        elif word == 'big':
            value = 0.5
        elif word == 'right':
            value = 0.45
    return (document, tail, counts), value

programs.haiku:
"""LaTeX size/delimiter commands: the word after a backslash (\\left, \\right, \\big, \\Big, \\middle)."""
READS = ()

# typical activation when the word follows a backslash
SIZE_WORDS = {"left": -15.0, "big": -13.0, "Big": -14.0, "middle": -13.0,
              "right": -6.0, "Left": -8.0, "Right": -8.0}

def step(carry, prefix, upstream):
    toks = prefix.token_strings
    if len(toks) >= 2 and toks[-2] == "\\":
        return carry, float(SIZE_WORDS.get(toks[-1], 0.0))
    return carry, 0.0

programs.sol:
"""Text cues for evidence, numerical proportions and remembered experience.

Additive rules recognize introduced studies and reports, citations, percentages,
calendar dates and recollections. A few contrasting cues (wants, conditional
phrases and middle-dot-only tokens) are negative. These are approximations, not
an exhaustive account of the component's responses. The state retains the
previous token and 100 characters, resets at document boundaries, and applies
a small negative offset at row/document starts.
"""
import calendar
import re
from functools import lru_cache

READS = ()

TIME_UNITS = frozenset(
    'centuries century day days decade decades month months week weeks '
    'year years'.split()
)
TIME_OF_DAY = frozenset('afternoon evening morning night'.split())
SEASONS = frozenset('autumn fall spring summer weekend winter'.split())
RELATIONS = frozenset(
    'dad daughter father friend friends husband mom mother son wife'.split()
)
PERCEPTION = frozenset('experienced heard noticed seen'.split())
EVIDENCE = frozenset(
    'interview interviews report reports research researcher '
    'researchers review reviews studies study survey surveys'.split()
)
INTRODUCERS = frozenset(
    'a an another clinical independent new one previous recent several '
    'some systematic'.split()
)
QUANTITIES = frozenset(
    'billions half hundreds majority many millions minority most '
    'number quarter quarters several some third thirds thousands'.split()
)
POSSESSIVES = frozenset('her his my our their your'.split())
MONTHS = frozenset(x.lower() for x in calendar.month_name if x)

WORD_CUES = (
    (0.467, 'studies study'),
    (0.215, 'recent'),
    (0.492, 'research researcher researchers'),
    (0.19, 'experiment experiments investigation investigations trial trials'),
    (0.304, 'survey surveys'),
    (0.204, 'interview interviews report reports review reviews'),
    (0.155, 'estimate estimates statistics'),
    (0.266, 'concluded conducted demonstrated estimated published reported revealed'),
    (0.329, 'recall remember'),
    (0.588, 'ago'),
    (0.502, 'once'),
    (0.53, 'ever'),
    (0.542, 'average averages'),
    (0.129, 'afternoon evening morning night'),
    (-0.139, 'want wants'),
    (0.117, 'billion billions hundred hundreds million millions thousand thousands'),
)
WORD_CUES = tuple((score, frozenset(words.split())) for score, words in WORD_CUES)

@lru_cache(maxsize=40000)
def lexical(token):
    word = token.strip().lower()
    value = sum(score for score, words in WORD_CUES if word in words)
    if word in MONTHS and token.strip()[:1].isupper():
        value += 0.156
    if word in {'据', '據', '根据', '根據'}:
        value += 0.174
    if word in {'某', '有人', '曾', '曾经', '曾經'}:
        value += 0.829
    if word in {'研究', '报告', '報告', '调查', '調查'}:
        value += 0.249
    if word in {'年', '月', '日'}:
        value += 0.169
    return value


def context_score(token, before, previous):
    word = token.strip().lower()
    prev = previous.strip().lower()
    value = lexical(token)

    # Contrasting textual cues.
    if token.strip() and set(token.strip()) == {'·'}:
        value += -0.984
    if word == 'once' and token.strip()[:1].isupper():
        value += -0.696
    if word == 'of' and prev == 'case':
        value += -0.731
    if word in {'want', 'need'} and prev == 'you':
        value += -0.437
    if word == 'ago' and (not token.startswith(' ')):
        value += -0.515

    # Numerical proportions.
    if '%' in token and prev.replace('.', '').isdigit():
        value += 0.508
    if word == 'of' and prev in {'half', 'third', 'thirds', 'quarter', 'quarters'}:
        value += 0.98
    if (
        word == 'of'
        and (prev in QUANTITIES
        or '%' in previous
        or prev in {'percent', 'percentage', 'cent'})
    ):
        value += 0.107
        if '%' in previous or prev in {'percent', 'percentage', 'cent'}:
            value += 1.472

    # Studies, reports, citations and examples.
    if word == 'al' and prev == 'et':
        value += 1.335
    if token == '-analysis' and prev == 'meta':
        value += 1.359
    if word == 'according' and token.strip()[:1].isupper():
        value += 0.64
    if word == 'recent' and prev in {'a', 'an'}:
        value += 1.416
    if word in {'study', 'studies'} and prev in INTRODUCERS:
        value += 0.917
    if word == 'study' and re.search('\\b(?:a|an)\\s+[12][0-9]{3}\\s*$', before, re.I):
        value += 0.969
    if word in {'by', 'published'} and prev == 'study':
        value += 1.548
    if (
        word in EVIDENCE | {'article', 'paper', 'estimates', 'statistics'}
        and 'according' in before.lower()[-65:]
    ):
        value += 0.827
    if word in {'据', '據'}:
        value += 1.207
    if word in EVIDENCE and prev in INTRODUCERS:
        value += 0.695
        if re.search('\\bin\\s+(?:a|one|another|a recent)\\s*$', before, re.I):
            value += 1.389
    if (
        word in {'recent', 'previous', 'new'}
        and re.search('\\bin\\s+a\\s*$', before, re.I)
    ):
        value += 0.395
    if (
        word in {'by', 'from', 'published', 'found', 'reported', 'showed'}
        and prev in EVIDENCE
    ):
        value += 0.784
    if 'according' in before.lower()[-45:]:
        if word in {'to', 'a', 'the'} or word in EVIDENCE:
            value += 0.215
    if (
        word == 'that'
        and prev in {'found', 'shown', 'reported', 'demonstrated', 'revealed'}
    ):
        value += 0.607
    if word == ',' and prev in {'example', 'instance'}:
        value += 0.32

    # Personal experience and recollection.
    if word in {'remember', 'recall'} and prev in {'i', 'we'}:
        value += 0.957
    if word == 'mine' and prev == 'of':
        value += 0.81
    if word == 'one' and prev in {'remember', 'recall'}:
        value += 0.991
    if word in RELATIONS and prev in POSSESSIVES | {'a', 'one'}:
        value += 0.192
    if word in PERCEPTION and prev in {'have', 'has', 'had', 'i', 'we'}:
        value += 0.173
    if (
        word in {'know', 'ever'}
        and re.search('\\b(?:did|have|do)\\s+you\\s*$', before, re.I)
    ):
        value += 1.529
    if word in {'one', 'time', 'point'} and prev in {'at', 'one', 'that'}:
        value += 0.137

    # Dates and relative times.
    text = before + token
    if word in MONTHS and prev in {'in', 'since', 'during', 'last'}:
        value += 0.561
    if (
        token.isspace()
        and previous in {'In', ' In', 'Since', ' Since', 'During', ' During'}
    ):
        value += 0.812
    if word in TIME_UNITS | TIME_OF_DAY | SEASONS:
        if prev in {'last', 'this', 'that', 'next', 'previous'}:
            value += 0.443
    if word == 'ago' and prev in TIME_UNITS | {'long'}:
        value += 0.343
    if re.search(
        '\\b(?:in|since|during|until|from)\\s+(?:1[5-9]|20)[0-9]{0,2}$',
        text,
        re.I,
    ):
        if re.search(
            '\\b(?:In|Since|During|Until|From)\\s+(?:1[5-9]|20)[0-9]{0,2}$',
            text,
        ):
            value += 0.356
    if word == '前' and re.search('(?:年|月|天|小时|小時)$', before):
        value += 0.68
    return value

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    initial = carry is None or carry[0] != doc
    if initial:
        before, previous = '', ''
    else:
        _, before, previous = carry
    token = prefix.token_strings[-1]
    value = context_score(token, before, previous)
    if initial:
        value += -0.2
    return (doc, (before + token)[-100:], token), float(value)

programs.haiku:
"""Layer 1 MLP unit 4627, read as a "statistics / citation / date" detector.

It is mostly silent. It turns on at the word that completes a stock phrase used when
reporting numbers, studies or dates:
  - "of" after a quantity: "25% of", "half of", "majority of" (strongest, ~1.5)
  - "al" in "et al" (~1.4)
  - research words: "study", "studies", "research", "report", "average" (~0.6)
  - "%" itself (~0.6), "ago", "ever", "once" (~0.7), month names (~0.4)
  - the first token of a year after "In" (e.g. "In 1932") (~0.9)
It goes negative on "of" in institution names or "in the case of" (~-0.5), and on
"want"/"need" after "you" as in "if you want" (~-0.9). Everything else predicts 0.
Limits: it captures only about 6% of the variance; the component's activity is spread
over many tokens, and a lookup table of token means would capture about 10-15%.
"""
READS = ()

PERCENT_WORDS = {"%", " %", " percent", " cent", " half", " majority", " thousands", " millions",
                 " many", " most", " some", " none", " couple"}
STUDY_WORDS = {" study", " studies", " research", " report", " reported", " review", " survey",
               " researchers", " average", " experiments"}
TIME_WORDS = {" ago", " ever", " once", " recent", " remember"}
MONTHS = {" January", " February", " March", " April", " May", " June", " July", " August",
          " September", " October", " November", " December"}

def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if cur == " of" and prev in PERCENT_WORDS:
        value = 1.5    # "25% of", "half of"
    elif cur == " al" and prev == " et":
        value = 1.4    # "Smith et al"
    elif cur == " of" and prev in (" case", " School", " Department", " District", " Museum"):
        value = -0.5   # "in the case of", "School of"
    elif cur in (" want", " need") and prev == " you":
        value = -0.9   # "if you want"
    elif cur in STUDY_WORDS:
        value = 0.6
    elif cur == "%":
        value = 0.6
    elif cur in TIME_WORDS:
        value = 0.7
    elif cur in MONTHS:
        value = 0.4
    elif cur in (" ", "1", "2") and prev in (" In", "In"):
        value = 0.9    # first token of a year after "In"
    else:
        value = 0.0
    return carry, value

programs.sol:
"""Approximate Japanese word-continuation signals, plus an initial-token offset.

A negative response is strongest when short kana pieces can continue a common
Japanese dictionary reading. Independent wordfreq counts weight JMdict readings;
no model activations or token-ID lookup table are stored here. The checks for
adding 'い' and 'る' distinguish adjective/verb-like continuations. Other rules
cover 'その', a small offset after '自', repeated middle dots, and mostly
negative document-initial values. This is only a partial surface approximation.
"""
from collections import defaultdict
from functools import lru_cache
import math
import regex
import jmdict
from wordfreq import get_frequency_dict

READS = ()
PARTICLES = frozenset('はがのにをでともへやかねよなぞさてば')

# Frequency mass of kana prefixes of dictionary words, from an independent corpus.
READING_PREFIX = defaultdict(float)
for word, frequency in get_frequency_dict('ja').items():
    if frequency < 1e-8 or not regex.search(
        r'[\p{Script=Han}\p{Script=Hiragana}\p{Script=Katakana}]', word
    ):
        continue
    readings = jmdict.readings(word)
    if regex.fullmatch(r'[\p{Script=Hiragana}\p{Script=Katakana}]+', word):
        readings = tuple(set(readings + (word,)))
    for reading in readings:
        for length in range(1, min(6, len(reading)) + 1):
            READING_PREFIX[reading[:length]] += frequency / len(readings)


@lru_cache(None)
def script(text, name):
    return bool(text) and bool(regex.fullmatch(r'\p{Script=' + name + r'}+', text))


@lru_cache(None)
def continuation(previous, current):
    # Search the last three kana for a possible beginning of a dictionary word.
    frequencies = []
    for length in range(1, min(3, len(previous)) + 1):
        fragment = previous[-length:]
        if not script(fragment, 'Hiragana'):
            break
        mass = READING_PREFIX.get(fragment + current, 0.0)
        frequencies.append(9 + math.log10(mass) if mass else 0.0)
    return frequencies


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    previous = '' if start else carry[1]
    state = (doc, s)
    text = s.strip()
    if start:
        if s.startswith('<|'):
            return state, 0.31
        if text.isdigit():
            return state, -0.11
        if len(text) > 3:
            return state, -0.60 if s.startswith(' ') else -0.80
        return state, -0.35
    if s == previous and text and set(text) == {'·'}:
        return state, -0.98
    if s == 'その':
        return state, 1.50
    fragment = len(previous) == 1 and previous not in PARTICLES
    if script(text, 'Hiragana'):
        frequencies = continuation(previous, s)
        strongest = max(frequencies, default=0.0)
        if frequencies and frequencies[0] >= 4.5:
            if fragment:
                adjective = bool(jmdict.glosses(previous + s + 'い'))
                verb = bool(jmdict.glosses(previous + s + 'る'))
                if verb:
                    value = -2.79 if adjective else -1.55
                else:
                    value = -1.16 if adjective else -0.76
                return state, value
            return state, -0.45 if len(previous) <= 2 else -0.10
        if strongest >= 3.5:
            return state, -0.49 if fragment else -0.19
        return state, -0.07 if len(previous) <= 1 else 0.0
    if fragment and script(previous, 'Katakana') and script(text, 'Katakana'):
        return state, -0.18
    if previous.endswith('自'):
        return state, 0.25
    return state, 0.0

"""Estimate a multilingual grammatical-plural signal.

Match the current word-so-far to plural articles, possessives, demonstratives,
and quantifiers. Recent word frequencies suggest which language is being read.
Romance articles get large values; English quantifiers get smaller ones. Also
recognize a few inflectional endings and contextual uses of English 'are/were'.
This is not a general plural-noun detector: most tokens predict zero.
"""
import regex as re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = ('en', 'fr', 'pt', 'es', 'de', 'it', 'ro', 'tr', 'pl', 'id')

@lru_cache(maxsize=20000)
def language_evidence(word):
    # Centered log frequencies: evidence for a language, not word identity.
    f = [max(1.5, zipf_frequency(word, lang)) for lang in LANGUAGES]
    mean = sum(f) / len(f)
    return tuple(x - mean for x in f)

# Each row is a grammatical class: (language, activation, forms).
MARKERS = (
    ('fr', 4.9, 'les des aux'),                    # plural articles
    ('fr', 6.2, 'mes tes ses nos vos'),            # possessives
    ('fr', 3.9, 'leurs'),
    ('fr', 6.3, 'ces'),                           # demonstratives
    ('fr', 3.5, 'tous toutes'),                   # universal quantifiers
    ('fr', 2.0, 'quelques ceux celles elles'),
    ('es', 5.4, 'los las'),
    ('es', 6.3, 'unos unas'),
    ('es', 7.1, 'mis tus sus'),
    ('es', 4.5, 'nuestros nuestras vuestros vuestras'),
    ('es', 3.8, 'estos estas esos esas aquellos aquellas'),
    ('es', 3.8, 'todos todas algunos algunas'),
    ('es', 2.5, 'otros otras muchos muchas ambos ambas'),
    ('pt', 7.5, 'os as dos das nos nas aos às pelos pelas'),
    ('pt', 6.2, 'esses essas estes estas aqueles aquelas'),
    ('pt', 6.2, 'desses dessas destes destas daqueles daquelas'),
    ('pt', 5.5, 'seus suas nossos nossas vossos vossas'),
    ('pt', 3.6, 'todos todas outros outras alguns algumas muitos muitas quais'),
    ('pt', 7.8, 'vocês'),
    ('it', 7.7, 'i le gli ai agli alle'),
    ('it', 6.1, 'dei degli delle dai dagli dalle nei negli nelle sui sugli sulle'),
    ('it', 4.6, 'tutti tutte questi queste quei quegli quelle '
                'suoi sue nostri nostre'),
    ('it', 3.2, 'li altri altre noi'),
    ('it', 4.0, 'tanti tante molti molte'),
    ('ro', 3.1, 'aceste acele acești aceşti cei cele toți toate'),
    ('ro', 2.5, 'sunt'),
)
MARKERS = {
    (language, form): value
    for language, value, forms in MARKERS
    for form in forms.split()
}
DEMONSTRATIVES = {'these', 'those'}
RUSSIAN_PLURAL = {'эти', 'те', 'другие', 'свои', 'наши', 'ваши', 'какие'}
DATIVE_PREPOSITIONS = {'mit', 'von', 'aus', 'zu', 'bei', 'seit'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', (0.0,) * len(LANGUAGES))
    _, word, previous, scores = carry
    raw = prefix.token_strings[-1]
    # One decaying language vote per completed word, not per subword token.
    for piece in re.findall(r'[^\W\d_]+|[\W\d_]+', raw.lower()):
        if piece.isalpha():
            word += piece
        elif word:
            evidence = language_evidence(word)
            scores = tuple(.85 * a + b for a, b in zip(scores, evidence))
            previous, word = word, ''
    token = raw.strip().lower()
    evidence = language_evidence(word) if word else (0.0,) * len(LANGUAGES)
    language = LANGUAGES[max(
        range(len(LANGUAGES)), key=lambda i: scores[i] + .4 * evidence[i]
    )]
    value = MARKERS.get((language, word), 0.0)
    # Single letters in formulas and identifiers are not Italian articles.
    if language == 'it' and word == 'i':
        confidence = scores[5] - max(scores[:5] + scores[6:])
        if confidence < 3.0:
            value = 0.0
        elif not raw[:1].isspace() and len(prefix.token_strings) > 1:
            if prefix.token_strings[-2][-1:] in '*+/_=^':
                value = 0.0
    if word == 'os' and language == 'pt':
        if scores[2] < max(scores[0], scores[4]):
            value = .15
    # Code identifiers are not grammatical words, even if a piece spells one.
    if value > 0 and len(prefix.token_strings) > 1 and not raw[:1].isspace():
        if prefix.token_strings[-2][-1:] in '/_.':
            value = 0.0
    if word in DEMONSTRATIVES:
        value = 1.65
    elif word == 'all':
        value = .73
    elif word in {'many', 'few', 'fewer'}:
        value = {'many': .28, 'few': .66, 'fewer': 1.7}[word]
    elif word == 'are':
        value = {'there': 2.3, 'here': 3.5, 'what': 6.1,
                 'how': 2.0, 'these': .65, 'those': .65}.get(previous, .02)
    elif word == 'were':
        value = 1.7 if previous == 'there' else .02
    elif word in RUSSIAN_PLURAL:
        value = 3.0
    elif word in {'этих', 'тех', 'всех', 'все', 'других',
                  'некоторые', 'такие', 'таких'}:
        value = 1.5
    elif token in {'ими', 'ыми', 'ними', 'ными'}:
        value = 2.4
    # Action-noun endings are singular, despite sharing final -ие.
    elif token.endswith(('ение', 'ание', 'ствие')):
        value = 0.0
    elif (re.fullmatch(r'\p{Script=Cyrillic}+(?:ые|ие)', token)
          and not raw[:1].isspace()):
        value = 1.65
    elif (re.fullmatch(r'\p{Script=Cyrillic}+(?:ых|их)', token)
          and not raw[:1].isspace()):
        value = 1.0
    elif token in {'ые', 'ие'}:
        value = 1.65
    elif token in {'ых', 'их'}:
        value = 1.0
    elif token == 'ς':
        value = 1.2
    elif word in {'των', 'τους', 'τις', 'οι'}:
        value = 2.7
    elif token in {'ích', 'ých'}:
        value = 1.5
    elif token == 'і' and not raw[:1].isspace():
        value = 1.1
    elif token in {'一些', '有些', '这些', '那些', '各', '各个'}:
        value = .6
    elif language == 'de':
        if word == 'die':
            value = .52
        elif word in {'alle', 'viele', 'keine', 'vielen'}:
            value = 1.3
        elif word in {'den', 'ihren', 'seinen', 'meinen', 'unseren', 'diesen'}:
            value = 5.3 if previous in DATIVE_PREPOSITIONS else 1.2
    if word == 'their':
        value = -.16
    return (doc, word, previous, scores), value

programs.haiku:
"""Plural determiners. The activation fires on the first token of a plural article,
possessive, demonstrative or quantifier in Romance and other non-English text (les, los,
sus, tutti, des, dei ...), and on English these/those/all and on 'are' after 'there' or
'what'. Words that are also singular or English (le, i, as, os, des, den, ai) count only
when the nearby text is not English."""
READS = ()

DEFINITE_PLURAL = {"les", "los", "las", "gli", "dei", "degli", "delle", "dalle", "alle",
                   "aux", "dos", "nas", "nos", "nelle", "nei", "dai", "ai", "aos"}
POSSESSIVE_PLURAL = {"sus", "ses", "ces", "mes", "nuestros", "nuestras", "leurs", "seus", "questi",
                     "suoi", "sue", "vos", "tus"}
QUANTIFIER_PLURAL = {"tutti", "tous", "toutes", "tutte", "todos", "unos", "altri", "outros"}
AMBIGUOUS = {"le": 0.7, "os": 2.7, "des": 2.8, "den": 1.3, "ai": 1.5}
DEMONSTRATIVE = {"these", "those"}
QUANTIFIER_ENGLISH = {"all", "few", "many", "fewer"}
GERMAN_PLURAL = {"diesen", "ihren", "unsere"}
RUSSIAN_PLURAL = {"все", "всех", "этих", "свои", "своими", "какие", "их", "ими", "ные", "ными", "ых", "ые"}
ENGLISH_WORDS = {"the", "of", "and", "is", "are", "to", "that", "with", "for", "it", "this", "was",
                 "be", "on", "by", "from", "an", "or", "which", "at", "not", "have", "has", "they",
                 "you", "we", "their", "these", "will", "can"}

def english_share(prefix):
    recent = [s.strip().lower() for s in prefix.token_strings[-31:-1]]
    return sum(w in ENGLISH_WORDS for w in recent) / max(1, len(recent))

def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    w = s.strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if prefix.position > 0 else ""
    starts_word = s.startswith(" ") or prefix.position == 0 or not prefix.token_strings[-2][-1:].isalpha()
    if w in RUSSIAN_PLURAL: return None, 1.5
    if not starts_word:
        return None, 0.0
    if w in DEFINITE_PLURAL: return None, 4.5
    if w in POSSESSIVE_PLURAL: return None, 5.0
    if w in QUANTIFIER_PLURAL: return None, 4.0
    if w in DEMONSTRATIVE: return None, 1.6
    if w in QUANTIFIER_ENGLISH: return None, 0.6
    if w in GERMAN_PLURAL: return None, 1.5
    if w == "are" and prev in ("there", "what"): return None, 2.7
    if w in AMBIGUOUS and english_share(prefix) < 0.15:
        return None, AMBIGUOUS[w]
    return None, 0.0

programs.sol:
"""Recognize question endings and the start of an answer/choice list.

Interrogative wording, an early document position, and user turns strengthen
question endings; explicit thinking spans weaken them. A single line break
gives a larger response than a paragraph break. Quotes and non-word
endings weaken it; URL queries are ignored. Smaller rules recognize
interrogatives and quantifier-of phrases. State is reset at document boundaries.
"""
import re

READS = ()
WH = re.compile(r'\b(who|what|when|where|why|how|which|whose|whom)\b', re.I)
PREPOSITIONS = set('of in on with from to for by about at'.split())
COPULAS = set('is are was were be'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        prev, older, tail, role, thinking, position = '', '', '', '', False, 0
    else:
        _, prev, older, tail, role, thinking, position = carry
    text = prefix.token_strings[-1]
    word, before = text.strip(), prev.strip()
    low = before.lower()
    lines = text.count('\n')
    value = 0.0

    # Only punctuation tokens count; letters attached to ? do not.
    if any(c in text for c in '?？؟') and not word.strip(
        '?!？！؟.。\"\'”’»)]}(\\ \n\t'
    ):
        if '؟' in text:
            value = 1.7
        else:
            value = 0.48 if prev.isascii() else 0.95
            value += 0.55 if lines == 1 else -0.06 if lines > 1 else 0
            value += 0.4 if WH.search(tail) else 0
            value += 0.4 if role == 'user' else 0
            value += 0.38 if position < 20 else 0
            value -= 0.35 if thinking else 0
            value -= 0.3 if not any(c.isalpha() for c in prev) else 0
            value -= 0.15 if '？' in text else 0
            value -= 0.35 if any(c in text for c in '\"\'”’»') else 0
            value += 0.15 if text.count('?') + text.count('？') > 1 else 0
        if '://' in tail or 'www.' in tail:
            value = 0.0
        value *= 1.15

    if word == 'of':
        if low == 'which':
            value = 3.5 if before[0].isupper() else 2.4
        elif low == 'one':
            value = 4.5 if older.strip().lower() == 'which' else 0.2
        elif low == 'none' or before == 'All':
            value = 1.0
        elif low == 'most':
            value = -0.25
        elif low == 'each':
            value = 0.2

    if word.lower() == 'what':
        value = 0.1
        if low in PREPOSITIONS:
            value = 0.6
        elif low in {'do', 'does', 'doing'}:
            value = 1.5
        elif low in COPULAS:
            value = 0.4
        elif before == ',':
            value = 0.3
    elif word.lower() in {'which', 'how'}:
        value = 0.35 if word == 'Which' else 0.0
        if low in COPULAS:
            value = 0.7
        elif low in PREPOSITIONS or before == ',':
            value = 0.15
    if word in {'哪', '何', '幾', '谁', '誰'}:
        value = 0.7
    elif word == '怎':
        value = 1.5
    elif word == 'か':
        value = 0.45

    # A at the beginning of a line often labels the first answer.
    if word == 'A' and '\n' in prev:
        value = 0.6 if prev.count('\n') == 1 else 0.25
        if '?' in prev or '？' in prev:
            value = 2.2 if prev.count('\n') == 1 else 1.2
    elif word in {'(A', '(a'} and '\n' in prev:
        value = 1.2
    if ':' in text and lines:
        value = 0.06
        if low == 'options':
            value = 1.8
        elif lines == 1 and low in COPULAS | {'include', 'includes', 'to'}:
            value = 0.6
    if prev == '<|im_start|>':
        role = text
    if text in {'<think>', '</think>'}:
        thinking = text == '<think>'
    state = (doc, text, prev, (tail + text)[-150:], role, thinking, position + 1)
    return state, value

"""Date boundaries, numerical separators, and the grammatical use of 'see'.

Date ranges and a year followed by a range marker or year suffix are negative. Opening
'In YEAR,' and 'between YEAR and' phrases are stronger than clause-final years.
A later hyphen in a short, hyphenated number is positive instead. A separate
rule distinguishes first-person 'I see' from prospective 'to/will see'.
Leading carriage returns have a negative response. Only a short suffix is
remembered, reset at document boundaries.
"""
import re
from calendar import month_name

READS = ()
MONTH_RANGE = re.compile(
    r"\b(?:from|between)[^.;\n]{0,35}\b(?:"
    + "|".join(month_name[1:]) + r")\Z", re.I
)


def predict(text, token):
    if token == '\r':
        return -2.84 if not text.strip('\r') else 0.0
    word = token.strip()
    if word in {'to', 'and'} and MONTH_RANGE.search(text):
        return -3.3
    if word == 'see':
        if re.search(r'\bI\Z', text):
            return 2.0
        if re.search(r"\bI (?:don't|do not)\Z", text):
            return 1.3
        if re.search(r'\b(?:will|shall|would)(?: \w+)?\Z', text):
            return -0.8
        if re.search(r'\bto\Z', text):
            return -0.3
        if re.search(r'\b(?:you|You|they|They|he|she)\Z', text):
            return 0.5
        return 0.1
    if word == 'seen':
        if re.search(r'\bhas\Z', text):
            return -2.3
        return -0.6 if re.search(r"(?:\bhave|['’]ve|\bnever)\Z", text) else 0.0
    if word == 'seeing':
        return -1.0 if re.search(r"\b(?:are|we're)\Z", text) else -0.4
    if token.isdecimal():
        padded_month = re.search(r'[12][0-9]{3}[-/.]\Z', text)
        return -1.1 if padded_month and token == '0' else 0.0
    match = re.search(r'(\d+)\Z', text)
    if not match:
        return 0.0
    digits = match[1]
    before = text[:match.start()].rstrip()
    size = len(digits)
    number = int(digits[-8:])
    year = size == 4 and 1000 <= number <= 2199
    strength = 1.0 if year and number >= 1700 else 0.55 if year else 0.0
    if word in {'-', '–', '—'}:
        spaced = token.startswith(' ')
        chain = bool(re.search(r'\d[-–]\Z', before))
        if chain and size <= 4:
            if spaced:
                return 0.5 if size <= 2 else 0.0
            return 3.8 if size == 1 else 1.2 if size <= 3 else 0.3
        if word == '—':
            return -0.4 if year else 0.0
        if year:
            amplitude = -2.4 if spaced else -4.8 if word == '–' else -5.1
            return amplitude * strength
        if size == 4:
            return -1.7 if not spaced else -0.3
        if spaced:
            return 0.1 if size <= 2 else -0.1
        if size >= 6:
            return -2.0
        if size >= 3:
            return -0.9
        return -0.5 if word == '–' else 0.0
    if not year:
        return -1.2 if size >= 4 and word in {'||', '|'} else 0.0
    if word in {'to', 'through', 'until'}:
        start = bool(re.search(r'\b[Ff]rom(?: \w+)?\Z', before))
        return (-6.3 if start and word == 'to' else -2.3) * strength
    if word in {'and', 'et', 'und'}:
        between = bool(re.search(r'\b[Bb]etween[^.;\n]{0,40}\Z', before))
        return (-6.0 if between else -1.1) * strength
    if word == '年代':
        return 0.0
    if word.startswith('年') or word == '년':
        return (-0.9 if word == '年度' else -4.3) * strength
    if word in {'г', 'году', 'года', 'гг', 'р', 'r', 'م'}:
        return (-6.2 if word in {'г', 'р', 'م'} else -4.0) * strength
    if word in {',', '，'}:
        if re.search(r'\bIn\Z', before):
            return -2.5 * strength
        if re.search(r'\b(?:since|until|by|before|after)\Z', before):
            return 0.0
        return -0.9 * strength
    if word == ';':
        return -2.3 * strength
    if word == ':':
        return -1.0 * strength
    if word == '/':
        return -1.0 * strength
    if word == '.':
        return -0.6 * strength if before.endswith(',') else 0.0
    if word in {'||', '|'}:
        return -1.6
    if word in {'he', 'she', 'they', 'the', 'it'}:
        return -1.3 * strength
    return -0.2 * strength if token.startswith(' ') and word.isalpha() else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = predict(text, token)
    return (doc, (text + token)[-160:]), value

"""A quantity-writing feature, with a few text-format responses.

These rules summarize recurring training patterns, not every lexical response.
Small number-word spellings are positive. Bare numerals near East Asian writing are
negative, particularly in dates. Short letter chunks in long base64-like
strings, partitive 'which/each one of', and opening title headers are positive.
Only a short, document-local text suffix is kept; no token IDs are used.
"""
import re
import regex
import inflect
from atoms import FULLWIDTH_DIGITS

READS = ()
_engine = inflect.engine()
ENGLISH = {_engine.number_to_words(n): n for n in range(20)}
FOREIGN_COUNTS = set("""
    deux trois quatre cinq six sept huit neuf dix
    zwei drei vier fünf sechs sieben acht neun zehn
    dos tres cuatro cinco seis siete ocho nueve diez
    due tre quattro cinque sei sette otto nove dieci
    dois duas três quatro sete oito
    два две три четыре пять шесть семь восемь девять десять
""".split())
EAST = regex.compile(r'[\p{Han}\p{Hiragana}\p{Katakana}\p{Hangul}]')
LETTERS = regex.compile(r'\p{L}+$')
# Chinese numerals and place-value units.
HAN_NUMBERS = set('一二三四五六七八九十百千零〇')


def predict(before, token, position):
    value = -0.0042
    if position == 0:
        value -= 0.048  # document start
    word_match = LETTERS.search(before + token)
    word = word_match.group().lower() if word_match else ''
    if token and token[-1].isalpha():
        n = ENGLISH.get(word, -1)
        if n == 1:
            value += 0.084  # one
        elif n == 2:
            value += 0.468  # two
        elif 3 <= n <= 4:
            value += 0.398  # three four
        elif 5 <= n <= 6:
            value += 0.347  # five six
        elif 7 <= n <= 19:
            value += 0.190  # larger small counts
        elif word in FOREIGN_COUNTS:
            value += 0.261  # foreign count
        if word in {'several', 'multiple'}:
            value += 0.148  # multiple
    if token.strip().lower() == 'of':
        if re.search(r'\bone\s*$', before, re.I):
            value -= 0.061  # one of
            if re.search(r'\b(each|every|any|which)\s+one\s*$', before, re.I):
                value += 1.357  # selected one of
        if re.search(r'\b(plurality|series|thousands)\s*$', before, re.I):
            value += 0.256  # plural group of
    s = token.strip()
    if s.isdecimal():
        value += 0.009  # digit
        last_letter = next((c for c in reversed(before[-120:])
                            if c.isalpha()), '')
        if last_letter and EAST.fullmatch(last_letter):
            value -= 0.383  # digit after east language
        if before and EAST.fullmatch(before[-1]):
            value -= 0.319  # digit adjacent east
        if re.search(r'[年月][0-9０-９]*$', before):
            value -= 0.470  # after year/month markers
        if before.endswith('第'):
            value += 0.345  # ordinal digit
        if any(c in FULLWIDTH_DIGITS for c in s):
            value -= 0.044  # wide digit
        if s == '1' and re.search(r'(?:^|\n)[ \t]*$', before):
            value -= 0.101  # line initial one
        if position < 3 and before.isspace():
            value += 0.690  # opening number after space
    if s and all(c in HAN_NUMBERS for c in s):
        if s != '一':
            value -= 0.300  # han number
            if before and before[-1] in HAN_NUMBERS:
                value -= 0.793  # han number sequence
    # Bare forms meaning 'how many/a few', 'two', and 'each'.
    if s in {'几', '幾', '两', '兩', '每'}:
        value -= 0.827  # han quantifier
    if before.endswith('每') and s.startswith('一'):
        value += 1.481  # each han quantity
    if s.isdecimal() or (token.isascii() and token.isalpha()
                         and len(token) <= 4):
        run = re.search(r'[A-Za-z0-9+/=]+$', before)
        if run and len(run.group()) >= 24:
            run = run.group()
            if (sum(c.isupper() for c in run) >= 3
                    and sum(c.islower() for c in run) >= 3
                    and sum(c.isdigit() for c in run) >= 2):
                if token.isascii() and token.isalpha() and len(token) <= 4:
                    value += 0.811  # encoded letters
                if s.isdecimal():
                    value += 0.865  # encoded digits
    if token in {'Ã', 'ã'}:
        value += 0.728  # encoding marker
    if position == 0 and token == 'Title':
        value += 2.989  # opening title
    if position == 1 and before == 'Title' and token == ':':
        value += 10.924  # title colon
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before, position = '', 0
    else:
        _, before, position = carry
    token = prefix.token_strings[-1]
    value = predict(before, token, position)
    return (doc, (before + token)[-160:], position + 1), float(value)

"""Approximate productive word endings, not arbitrary token identities.

Role nouns (-er, -or, -ant, -ent), recipient nouns (-ee), and possibility
endings (-able, -ability) respond mainly when an ending completes a word.
WordNet supplies person senses and possible verb stems; English frequency
estimates how novel the derivative is. Whole-word tokens are left at zero.
There are also small corrections for -itor, the person marker 者, and document starts.
"""
import re
from functools import lru_cache
import wordnet
from wordfreq import zipf_frequency

READS = ()
ENDINGS = ('ability', 'ibility', 'able', 'ible',
           'er', 'or', 'ee', 'ant', 'ent')

@lru_cache(maxsize=50000)
def word_info(word):
    # In an identifier, examine its final CamelCase word.
    parts = re.findall(r'[A-Z]?[a-z]+|[A-Z]+(?![a-z])', word)
    word = (parts[-1] if parts else word).lower()
    if word.endswith('s') and not word.endswith('ss'):
        word = word[:-1]
    ending = next((s for s in ENDINGS if word.endswith(s)), '')
    if not ending or len(word) <= len(ending):
        return None
    stem = word[:-len(ending)]
    stems = [stem, stem + 'e']
    if len(stem) > 2 and stem[-1] == stem[-2]:
        stems.append(stem[:-1])
    if stem.endswith('i'):
        stems.append(stem[:-1] + 'y')
    verbs = [s for s in stems if 'verb' in wordnet.parts_of_speech(s)]
    if not verbs:
        unprefixed = [s[2:] for s in stems
                      if s.startswith(('un', 're')) and len(s) > 4]
        verbs = [s for s in unprefixed
                 if 'verb' in wordnet.parts_of_speech(s)]
    root_frequency = max((zipf_frequency(s, 'en') for s in verbs), default=0.)
    return (ending, root_frequency, zipf_frequency(word, 'en'),
            wordnet.categories(word), len(word))

@lru_cache(maxsize=50000)
def ending_value(token, word, attached):
    info = word_info(word)
    if info is None:
        return 0.
    ending, root_frequency, frequency, categories, length = info
    if not attached or len(token) >= length:
        return 0.
    direct = token.lower() in (ending, ending + 's')
    person = 'noun.person' in categories
    gap = max(0., root_frequency - frequency - .5)
    if ending == 'ee' and frequency < 4.2:
        return 3.5 if person else .5 if not categories else 0.
    if ending in ('able', 'ible', 'ability', 'ibility'):
        if direct and root_frequency:
            return min(.6, .07 + .19 * gap)
        return 0.
    if token.lower() in ('itor', 'itors'):
        return -.2
    if ('noun.artifact' in categories or 'noun.substance' in categories
            or 'noun.quantity' in categories
            or ('adj.all' in categories and not person)):
        return 0.
    if root_frequency and frequency < 4.3:
        if person:
            if direct:
                return min(1.9, .7 + .27 * gap)
            return min(.6, .22 + .085 * gap)
        return min(.63, .2 + .09 * gap) if direct else 0.
    return .35 if direct and person and frequency < 4. else 0.

def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    same_doc = carry is not None and carry[0] == doc
    oldword, previous = carry[1:] if same_doc else ('', '')
    token = prefix.token_strings[-1]
    match = re.search('[A-Za-z]+$', token)
    if match:
        word = oldword + match[0] if len(match[0]) == len(token) else match[0]
    else:
        word = ''
    attached = bool(oldword and re.fullmatch('[A-Za-z]+', token))
    value = ending_value(token, word, attached)
    if token == '者':
        value = .53
    if not same_doc:
        value -= .16
    elif previous == '<|endoftext|>' and token[:1].isalpha():
        value -= .24
    return (doc, word, token), float(value)

"""A sparse approximation of a document-edge and source-syntax component.

Large positive responses mark PHP openings, HTML declarations and shebangs;
issue-comment preambles have the opposite sign. A GitHub-star header
is also positive. At other document starts,
space-prefixed English words tend positive, bare lowercase words negative.
Dictionary action/cognition classes refine this first-word estimate.
Small offsets cover some ordinary source punctuation and tool delimiters.
The component's many other word-specific fluctuations are not reproduced.
"""
import wordnet

READS = ()

# These are dictionary classes, not a list of memorized token spellings.
START_CLASSES = {
    'verb.cognition': 0.10,
    'verb.communication': 0.05,
    'verb.social': 0.08,
    'verb.consumption': 0.16,
    'adv.all': 0.10,
    'noun.act': 0.07,
    'noun.state': 0.06,
    'noun.substance': -0.10,
    'noun.shape': -0.10,
    'noun.relation': -0.09,
    'noun.phenomenon': -0.07,
    'noun.artifact': -0.05,
    'noun.attribute': -0.05,
    'noun.quantity': -0.04,
    'noun.cognition': -0.05,
    'noun.time': -0.04,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        age, opening = 0, ''
    else:
        _, age, opening = carry
    if age < 5:
        opening += token

    word = token.strip()
    value = 0.002
    if age == 0:
        if not word:
            value = -0.10
        elif word.isascii() and word.isalpha():
            if len(word) > 1:
                value = -0.07 + 0.14 * token.startswith(' ')
                value += 0.05 * word.istitle() + 0.25 * word.isupper()
                classes = wordnet.categories(word.lower())
                value += sum(START_CLASSES.get(c, 0.0) for c in classes)
            elif token.startswith(' '):
                value = 0.10
            elif word.islower():
                value = -0.085
        if token == '<!':
            value = 3.896
        elif token == '#!':
            value = 1.444
        elif token == '<?':
            value = -0.317
        elif token == '<':
            value = -0.154
    else:
        if word in ('{', '}'):
            value = -0.018
        elif word in ('/', '|', '_'):
            value = 0.023
        elif word == '+':
            value = -0.025
        elif word == "'":
            value = 0.015
        elif word == '```':
            value = -0.10
        elif token in ('import', 'from'):
            value = -0.15
    if token == '<|im_start|>':
        value = -0.045
    elif token in ('<tool_call>', '<tool_response>'):
        value = -0.06
    elif token in ('</tool_call>', '</tool_response>'):
        value = 0.04

    if age == 1 and opening == '<?php':
        value = 1.118
    elif age == 4 and opening == '<issue_start><issue':
        value = -1.432
    elif age < 5 and opening == '<gh_stars':
        value = 1.048
    return (doc, age + 1, opening), value

"""Approximate local number and shortness/end-point responses.

30/31 are negative, especially after month or clock cues; the response is
weaker inside longer or decimal numerals. 20 gives a small positive signal.
Other negatives cover 'thirty', 'short/shortly', 'kurz/kort', 'just before'
or 'just shy', and 'end/most of'. Earlier number-scale words suppress
'thirty'. Capitalization and token boundaries affect these rules.
Keep at most 100 characters of history, resetting between documents.
Less regular word-fragment responses are deliberately left unmodeled.
"""
import calendar
import re
import unicodedata

READS = ()
MONTH = re.compile(
    r'(?:\b(?:' + '|'.join(calendar.month_name[1:]) + '|' +
    '|'.join(calendar.month_abbr[1:]) + r')\.?\s*|月)$', re.I
)
NUMBER = re.compile(r'([0-9]+)([.,]?)$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = unicodedata.normalize('NFKC', prefix.token_strings[-1])
    value = 0.0
    if token in ('0', '1'):
        match = NUMBER.search(tail)
        if match:
            digits, separator = match.groups()
            before = tail[:match.start()]
            fraction = bool(re.search(r'[0-9][.,]$', before))
            first = len(digits) == 1 and not fraction
            month = bool(MONTH.search(before))
            if digits.endswith('3'):
                value = (-5.2 if first else -2.6) if token == '0' else (
                    -3.3 if first else -1.4
                )
                if separator:
                    value *= 0.5 if token == '0' else 0.6
                    if separator == ',' and token == '1':
                        value *= 0.4
                elif first and month:
                    value = -10.8 if token == '0' else -8.8
                elif first and before.endswith((':', '時', '时')):
                    value = -6.8 if token == '0' else -3.5
            elif digits.endswith('2') and token == '0':
                value = (0.8 if month else 0.43) if first else 0.07
                if separator:
                    value *= 0.5
    word = token.strip()
    lower = word.lower() if not (len(word) > 1 and word.isupper()) else ''
    if lower in ('short', 'shorts'):
        value = -1.6 if token.startswith(' ') else -1.0
        if re.search(r'\ba$', tail, re.I):
            value = -2.4
    elif lower == 'shortly' or (lower == 'ly' and tail.lower().endswith('short')):
        capital = word[:1].isupper() and token.startswith(' ')
        value = -8.3 if capital or tail.endswith('Short') else -6.0
    elif lower in ('kurz', 'kort'):
        # German and Dutch/Nordic words for 'short'.
        value = -10.0 if lower == 'kurz' else -7.0
    elif lower == 'thirty':
        value = -5.5 if word[:1].isupper() else -3.1
        if re.search(r'\b(?:hundred|thousand|million|billion)(?: and)?$', tail, re.I):
            value = 0.25
        elif re.search(r'\blast$', tail, re.I):
            value = -5.2
    elif lower in ('before', 'shy'):
        value = (-7.5 if lower == 'shy' else -5.5) if re.search(
            r'\bjust$', tail, re.I
        ) else (
            -2.3 if lower == 'shy' else -0.3
        )
    elif lower == 'of':
        if re.search(r'\bend$', tail, re.I):
            value = -3.6 if re.search(
                r'\b(?:at|by|towards?) the end$', tail, re.I
            ) else -2.1
        elif re.search(r'\bmost$', tail, re.I):
            value = -1.4
    return (doc, (tail + token)[-100:]), value

"""Approximate a strong Spanish 'lo' response and weaker neuter-reference forms.

Use recent word frequencies to separate Romance reference words from English
word beginnings. Also respond to word-initial thought/feeling kanji in Japanese
context, and negatively to the colon in an opening 'Title:' header. Other responses,
including most character-specific Japanese variation, are left at zero.
"""
import re
from functools import lru_cache
import regex
import unihan
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = ('es', 'pt', 'en', 'fr', 'it', 'de')
SPANISH_REFERENCE = {'eso': 4.7, 'esto': 3.3, 'ello': 2.0,
                     'algo': 3.2, 'aquello': 4.0}
PORTUGUESE_REFERENCE = {'isso', 'isto', 'aquilo', 'disso', 'disto',
                        'nisso', 'nisto'}
REFERENCE = {'lo'} | SPANISH_REFERENCE.keys() | PORTUGUESE_REFERENCE
WORDS = re.compile(r'[^\W\d_]+')


@lru_cache(maxsize=20000)
def frequencies(word):
    return tuple(max(0.0, zipf_frequency(word, lang) - 2)
                 for lang in LANGUAGES)


def language(text):
    text = re.sub(r'<[^>]*>(?:assistant|user|system)?', ' ', text)
    words = WORDS.findall(text.lower())[-30:]
    if not words:
        return None
    scores = [sum(frequencies(w)[i] for w in words) / len(words)
              for i in range(len(LANGUAGES))]
    best = max(range(len(scores)), key=scores.__getitem__)
    return LANGUAGES[best] if scores[best] > 1.5 else None


def reference_value(token, word, recent, count):
    piece = token.strip().lower()
    if word not in REFERENCE and piece not in {'lo', 'dis', 'dist'}:
        return 0.0
    lang = language(recent)
    if piece == 'lo' and word != 'lo':
        return 1.5 if lang == 'es' and not token.isupper() else 0.0
    if word == 'lo':
        if lang == 'es':
            words = WORDS.findall(recent.lower())
            last = words[-1] if words else ''
            value = 10.7 if token.startswith(' ') else 9.0
            if last in {'de', 'en', 'a', 'todo'}:
                value = 12.8
            elif last in {'se', 'no'}:
                value = 7.0
            return value + (2.0 if token.strip() == 'Lo' else 0.0)
        if token.strip() == 'Lo':
            return 1.2
        if lang == 'pt' and token.startswith(' '):
            return 3.5
        return 3.0 if lang is None and count == 0 and token == ' lo' else 0.0
    if word in SPANISH_REFERENCE:
        if lang == 'es':
            return SPANISH_REFERENCE[word] + (1.8 if piece != word else 0.0)
        return 2.8 if word == 'algo' and lang == 'pt' else 0.0
    if word in PORTUGUESE_REFERENCE and lang == 'pt':
        return 2.8 + (1.5 if piece != word else 0.0)
    if piece in {'dis', 'dist'} and token.startswith(' ') and lang == 'pt':
        return 2.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent, previous, count, stem = '', '', 0, ''
    else:
        _, recent, previous, count, stem = carry
    token = prefix.token_strings[-1]
    tail = re.search(r'[^\W\d_]+$', token)
    word = tail.group().lower() if tail else ''
    if tail and tail.start() == 0:
        word = stem + word
    value = reference_value(token, word, recent, count)
    if (len(token) == 1 and regex.fullmatch(r'\p{Han}', token)
            and regex.search(r'\p{Hiragana}', recent[-100:])):
        meaning = unihan.definition(token) or ''
        # A preceding kanji usually makes this part of a compound noun.
        compound = bool(regex.fullmatch(r'\p{Han}', recent[-1:]))
        if not compound:
            if re.match(r'think\b', meaning):
                value = 5.0
            elif re.match(r'(mind|heart|know|terror|fear|anger|worry)\b', meaning):
                value = 3.0
    if token == ':' and previous == 'Title' and count <= 2:
        value = -5.49
    carry = (doc, (recent + token)[-600:], token, count + 1, word[-80:])
    return carry, value

"""Approximate the negative 'ma' spelling feature.

Short continuation pieces ending in ma respond most strongly. Word-initial
and longer pieces respond less. Transliteration covers other scripts;
Japanese ma is stronger when its character ends in a separate byte token.
Among single Han ma characters, jade-radical forms get a stronger response.
The state decodes split UTF-8 characters and resets at document boundaries.
This intentionally leaves finer contextual changes unexplained.
"""
import codecs
import unicodedata
import unihan
from anyascii import anyascii

READS = ()
JADE_RADICAL = 96
VOWEL_MA = {
    'a': -2.12,
    'e': -3.90,
    'i': -1.92,
    'o': -3.06,
    'u': -2.26,
}
SPLIT_ENDINGS = {
    'as': -2.11,
    'aa': -1.99,
    'ah': -0.97,
}


def response(text, previous, partial):
    roman = anyascii(text).lower()
    old = anyascii(previous).lower()
    if old.endswith('m'):
        if roman == 'a':
            name = unicodedata.name(text[0], '')
            if 'GREEK' in name:
                return -4.11
            if 'CYRILLIC' in name:
                return -1.04
            return -3.92 if text.isascii() else -1.37
        if roman in SPLIT_ENDINGS:
            return SPLIT_ENDINGS[roman]
    if text == 'ا' and previous.endswith('م'):
        return -2.4
    if text.endswith('ما'):
        return -0.47

    space = text[:1].isspace()
    if roman.endswith('ma'):
        nonlatin = any(c.isalpha() and ord(c) > 127 and
                       'LATIN' not in unicodedata.name(c, '') for c in text)
        if nonlatin:
            if len(text) > 1:
                return -0.26
            name = unicodedata.name(text, '')
            if 'CJK' in name:
                return -3.02 if unihan.radical(text) == JADE_RADICAL else -0.29
            if 'HIRAGANA' in name or 'KATAKANA' in name:
                return -3.89 if partial else -1.05
            return -1.01
        if text.istitle() and not text.isupper():
            return -0.55
        letters = roman.strip()
        if len(letters) == 2:
            if space:
                return -1.81 if text.isupper() else -0.44
            if not old or not old[-1].isalpha():
                return -1.78 if text.isupper() else -1.50
            if old.endswith('m'):
                return -2.76
            if old[-1] in 'aeiouy':
                return -2.66 if text.isupper() else -3.26
            return -5.82 if text.isupper() else -5.05
        if space:
            return -0.63
        if len(letters) == 3 and letters[0] in VOWEL_MA:
            return VOWEL_MA[letters[0]]
        return -0.28 if roman.endswith('mma') else -0.80
    if not space and len(roman) <= 4 and roman.endswith('mas'):
        return -1.18
    if not space and roman == 'mah':
        return -1.59
    return -0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        decoder = codecs.getincrementaldecoder('utf-8')(errors='ignore')
        previous = ''
    else:
        _, decoder, previous = carry
    raw = prefix.token_bytes[-1]
    text = decoder.decode(raw)
    partial = bool(raw) and 128 <= raw[0] < 192
    value = response(text, previous, partial)
    if text:
        previous = text[-24:]
    return (doc, decoder, previous), value

"""Mark the end of an uppercase word or short uppercase heading.

Periods, colons and whitespace give negative pulses, stronger after longer
uppercase spans. Short acronyms are mostly quiet, except figure references.
Underscores/digits weaken the response to code identifiers. Immediately
following whitespace can retain a small echo. Each document resets state and
gets a small first-token baseline offset.
"""
import re

READS = ()
FIGURE_LABELS = {'FIG', 'FIGS'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        carry = (doc, '', '', 0.0)
    _, text, previous, pulse = carry
    s = prefix.token_strings[-1]
    match = re.search(r'\w+\Z', text)
    word = match.group() if match else ''
    upper = sum(c.isupper() for c in word)
    previous_upper = sum(c.isupper() for c in previous)
    lower = sum(c.islower() for c in s)
    span = 0
    for char in reversed(text):
        if char.isupper():
            span += 1
        elif char not in ' \t':
            break
    size = max(upper, span)
    ending = (word.isupper() and not s.isupper()
              and not s.startswith('_') and not s.lstrip()[:1].isdigit())

    value = 0.0
    if ending:
        if word in FIGURE_LABELS and '.' in s:
            value = -2.9
        elif size <= 4:
            if previous_upper >= 3:
                if ':' in s or '.' in s:
                    value = -1.5
                elif s.isspace():
                    value = -0.5
            elif upper == 4 and lower == 0:
                value = -0.3
        elif ':' in s:
            value = -4.4 if size >= 9 else -3.4
        elif '.' in s:
            value = -3.2 if size >= 7 else -2.1
        elif s.isspace():
            value = -2.3 if size >= 7 else -1.8
        elif ',' in s:
            value = -2.0 if size >= 7 else -1.3
        else:
            value = -1.2 if span > upper else -0.5
        if '_' in word or any(c.isdigit() for c in word):
            value *= 0.2
        if '.' in s and lower:
            value *= 0.1  # e.g. an uppercase filename followed by .md
        if span >= 40:
            value *= 0.25  # a long uppercase passage, rather than a short heading
    elif s.isspace() and '\n' not in previous and '\r' not in previous:
        value = 0.3 * pulse
    if first:
        value = -0.05 if s.isspace() else 0.15
    next_pulse = value if ending else 0.0
    return (doc, (text + s)[-120:], s, next_pulse), float(value)

"""A document-start pulse, graded by the first token's written form.

It is strongly negative on words, weaker on digits and punctuation, and
small on line/paragraph endings. Case, word length and leading whitespace
refine the word estimate. The pulse persists through an initial run of
identical tokens; once a different token appears, the prediction is zero.
Hash markers and middle-dot leaders get stronger punctuation pulses.
These classes approximate, rather than memorize, token-specific amplitudes.
"""

READS = ()


def initial_pulse(text):
    word = text.strip()
    if text.startswith('<|'):
        return -9.4 if text == '<|im_start|>' else -4.5
    if text.isspace():
        if '\n' in text:
            return -0.6 if text.count('\n') > 1 else -2.7
        if '\t' in text or '\r' in text:
            return -7.0
        if not text.isascii():
            return -10.0
        return -1.9 if len(text) == 1 else -4.9 if len(text) == 2 else -6.8
    if word.isdigit():
        return -5.4
    if '\ufffd' in text:
        return -4.7
    if not any(ch.isalpha() for ch in text):
        if word and set(word) == {'·'}:
            return -18.9
        if word and set(word) == {'#'}:
            return -8.2
        return -2.5 if '\n' in text else -3.3
    if word.startswith('#'):
        return -2.1  # hash-prefixed words, such as preprocessor directives
    if not word.isalpha():
        return -7.7
    if not word.isascii():
        return -9.4
    spaced = text.startswith(' ')
    long = len(word) > 4
    if word.islower():
        value = -10.3 if spaced else -9.4
        return value + ((0.8 if spaced else 1.5) if long else 0.0)
    if word.istitle():
        return -12.8 + 2.1 * long + 1.5 * spaced
    return -11.8 + 3.5 * spaced + 1.0 * long


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_bytes[-1]
    if carry is None or carry[0] != document:
        value = initial_pulse(prefix.token_strings[-1])
        return (document, token, value, True), value
    doc, first_token, value, active = carry
    active = active and token == first_token
    return (doc, first_token, value, active), value if active else 0.0

"""Detect an English -s added to an initialism, letter, or numeral.

A separately tokenized plural -s after an all-capital abbreviation is strongest.
Apostrophe-s and an -s fused with the abbreviation's last capital are weaker.
Ordinary word possessives and contractions get little positive response.
Decimal seconds are weaker than numeral plurals or decade names. Counting
language strengthens plurals of individual letters and numerals. The same
plural marker after a closed math expression, bracket, or code quotation is
also recognized; ordinary split apostrophes have a much smaller response.
Spelling-based code-context rules downweight filenames and SQL table names,
and distinguish test timings from other decimal second values. This leaves
individual abbreviations' strengths and most background activity unmodeled.
"""
import re

READS = ()


def counted(before):
    # An explicit quantifier immediately before the name of a symbol.
    return bool(re.search(
        r'\b(?:two|three|four|five|six|seven|eight|nine|many|multiple|more|'
        r'leading|trailing|number of|count of)\s+[A-Za-z0-9]+\Z',
        before, re.I))


def predict(before, token):
    if not token.endswith(('s', 'S')):
        return 0.0
    match = re.search(r'[A-Za-z0-9_]+\Z', before)
    root = match[0] if match else ''
    if token == '$s' and before.count('$') % 2:
        return 3.5
    if token == ';s' and re.search(r'&#(?:39|x27)$', before):
        return 1.0
    if token in ("'s", '’s', '‘s', "'S", '’S'):
        if len(root) == 1 and root.isalnum() and counted(before):
            return 6.5
        if root.isalpha() and root.isupper():
            return 2.0 if len(root) > 1 else 3.3
        if len(root) == 1 and root.isalpha():
            return 3.3
        if root and root[-1].isdigit():
            return 2.35
        if root.lower() in {'it', 'he', 'she', 'that', 'there', 'here',
                            'who', 'what', 'where', 'how', 'let'}:
            return -0.02
        return -0.13
    if token == 's':
        if re.search(r'(?:\\x99|&#(?:39|x27);?)$', before):
            return 0.9
        if before.endswith(("'", '’', '‘')):
            stem = before[:-1].rstrip()
            if stem.endswith('$'):
                return 6.0
            if (stem.endswith((')', ']', '>', '`'))
                    or re.search(r'(?:[A-Z]\.){2,}\Z', stem)):
                return 4.0
            return -0.2 if stem.endswith(('(', '[', '{')) else 0.4
        if before.endswith((']', '>', '`')):
            return 2.8
        if re.fullmatch(r'[A-Z]{2,}', root):
            # Downweight acronym-shaped filenames and SQL names.
            head = before[:-len(root)]
            if (head.endswith(('/', '\\'))
                    or re.search(r'\b(?:FROM|UPDATE|TABLE)\s+\Z', head)):
                return 3.0
            return 7.0
        if (root.isalpha() and len(root) <= 6
                and sum(c.isupper() for c in root) >= 2
                and sum(c.islower() for c in root) <= 1):
            return 5.0
        if root.isdigit():
            if re.search(r'\d+\.\d+$', before):
                testing = re.search(
                    r'\b(?:PASS|Test\w*|passed|passing)\b', before)
                return 1.0 if testing else 0.3
            if len(root) == 4:
                return 2.1
            if counted(before) and not (len(root) == 2 and root[-1] == '0'):
                return 6.8
            return 1.8
        if len(root) == 1 and root.isalpha() and counted(before):
            return 6.5
        if root and root[-1].isdigit():
            return 1.0
        return 0.0 if root.isalpha() and len(root) > 1 else -0.1
    if re.fullmatch(r' ?[A-Z]s', token) and re.search(
            r'\b(?:[2-9]|two|three|four|five|six|seven|eight|nine|many|multiple)'
            r'\s*\Z',
            before, re.I):
        return 3.5
    if re.fullmatch(r'[A-Z]+s', token):
        if root and re.fullmatch(r'[a-z]{0,8}[A-Z]+', root):
            return 2.8
        return -0.35
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    before = '' if carry is None or carry[0] != document else carry[1]
    token = prefix.token_strings[-1]
    value = predict(before, token)
    return (document, (before + token)[-120:]), value

"""Detect opening formatting, not the topic of the following document.

The main response is at document start: Markdown headings, even-width
indentation, and source-code/comment openers.  The numbers calibrate these
recognizable syntactic forms.  A leading run of the same token keeps its
opening response.  A few short header patterns have a follow-on response;
other initial words get a small baseline based on leading space.  Later
prose and later occurrences of the markers are left at zero.
"""
READS = ()

# Space counts, rather than token identities: common even indentation widths.
INDENT = {2: 3.37, 4: 4.64, 6: 4.37, 8: 3.60,
          10: 2.48, 12: 2.66, 14: 1.47, 16: 3.24}
HEADINGS = {1: 3.76, 2: 2.47, 3: 2.61, 4: 2.62, 5: 3.17, 6: 1.90}

# Opening delimiters: Markdown emphasis, comments, strings, and templates.
OPENERS = {
    ' #': 7.80, '**': 2.84, '__': 1.58, '```': 1.51,
    '"""': 3.36, '"""\n': 2.16, "'''\n": 3.74,
    '//': 0.82, '//\n': -1.30, '///': 1.62,
    '/*': 0.92, '/*\n': 0.90, '/*\r\n': 1.55,
    '/**': 2.27, '/**\n': 2.16, '%': 1.91,
    '{{': 2.48, '{': 1.36, '(': 0.70, '[': 0.77,
    '<?': 0.67, '<': 0.64, '<!': -1.96, '^^^^': 0.81, '··': 0.46,
}

# Language preambles and declaration keywords, only when document-initial.
CODE = {
    'using': 2.13, 'public': 3.01, 'namespace': 1.84,
    'function': -2.35, 'def': -1.04, 'class': -0.68,
    'const': -0.80, 'var': -1.21, 'string': 2.53, 'int': 0.82,
    'import': -0.22, 'from': 0.97, 'package': 0.33, 'export': 1.37,
    '#ifndef': 1.75, '#include': -0.45, '#pragma': 1.09,
    '#define': 0.73, '#!/': 0.93,
}


def opening_value(token):
    if token and set(token) == {'#'}:
        return HEADINGS.get(len(token), 0.0)
    if token and set(token) == {' '}:
        return INDENT.get(len(token), 0.30 if len(token) == 1 else 0.0)
    if token == '\r':
        return 1.03
    if token == '\r\n':
        return 1.91
    if token in ('\n', '\n\n'):
        return 0.28
    if token in OPENERS or token in CODE:
        return OPENERS.get(token, CODE.get(token, 0.0))
    if token.isascii() and token.isalpha():
        return 0.13
    if token.startswith(' ') and token[1:].isascii() and token[1:].isalpha():
        return -0.06
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    first = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    if first:
        value = opening_value(token)
        return (token, raw, value), value
    if carry is not None:
        initial, initial_bytes, value = carry
        if raw == initial_bytes:
            return carry, value
        # The punctuation finishing an opening title or comment header.
        if initial == 'Title' and token == ':':
            return None, 1.21
        if initial == '//\n' and token == '//':
            return None, 1.67
        if initial == ' ' and token == ' #':
            return None, 2.30
    # Prefix of the second tag in <issue_start><issue... markup.
    if (token == 'issue' and prefix.position >= 4 and
            prefix.document_ids[-1] == prefix.document_ids[-5] and
            ''.join(prefix.token_strings[-5:]) == '<issue_start><issue'):
        return None, -2.12
    return None, 0.0

"""Approximate an EIN/AIN spelling signal, strongest at subword boundaries.

Completing a diphthong-plus-N spelling across tokens gets a large positive
value. Contained spellings get smaller values, with a separate rule for the
German name ending -stein. Transliteration extends these spelling rules to
some other alphabets. A + IP is an inhibitory spelling contrast.
Amplitudes approximate training-group means; word-specific irregularities
and weak background activations are not modeled. State resets per document.
"""
import re
from functools import lru_cache

import regex
from anyascii import anyascii

READS = ()
ALPHABETS = regex.compile(
    r'[\p{Latin}\p{Cyrillic}\p{Greek}\p{Katakana}'
    r'\p{Hiragana}\p{Hebrew}\p{Arabic}]'
)


@lru_cache(maxsize=32768)
def spelling(text):
    # Do not turn Chinese characters, for example, into pinyin syllables.
    if any(c.isalpha() and not ALPHABETS.fullmatch(c) for c in text):
        return ' '
    return anyascii(text).lower()


def activation(token, tail):
    t = spelling(token)
    word = t.strip()
    if not word:
        return 0.0
    if not t[0].isspace():
        if re.search(r'(ai|ay|ei|ey|ee)$', tail) and t.startswith('n'):
            return 5.5 if t == 'n' else 1.0
        if tail.endswith('e'):
            if t == 'in':
                # Liquids, nasals, and W before E give a weaker response.
                return 3.8 if re.search(r'[rlmnw]e$', tail) else 6.6
            if t == 'ine':
                return 2.3
            if t.startswith('in'):
                return 2.9 if len(t) <= 4 else 0.1
            if t.startswith('ign'):
                return 2.6
            if t.startswith('yn'):
                return 5.9
        if tail.endswith('a') and t.startswith(('in', 'yn')):
            return 3.1
        if tail.endswith('o') and t.startswith(('in', 'yn')):
            return 3.0 if len(t) == 2 else 0.6
        if tail.endswith('a') and t == 'ip':
            return -5.4

    if word.endswith('stein'):
        return 6.0
    match = re.search(r'e[iy]n', word)
    if match:
        if match.end() != len(word):
            return 0.2
        if not t[0].isspace():
            return 1.9 if len(word) <= 6 else 0.0
        if token.strip()[0].isupper():
            return 2.2
        return 1.6 if len(word) <= 4 else 0.1
    if re.search(r'a[iy]n', word):
        if len(word) == 3:
            return 1.6
        return 0.1 if t[0].isspace() else 0.3
    if word == 'oin':
        return 1.1
    if 'eign' in word and len(word) <= 5:
        return 1.9
    if (re.search(r'[aeiou][iy]n$', tail) and not t[0].isspace()
            and t.isalpha() and len(t) <= 2):
        return 0.6
    if token in ('יין', 'ין', 'ين', 'ین'):
        return 0.4
    return -0.1 if t == 'in' else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = activation(token, tail)
    return (doc, (tail + spelling(token))[-16:]), value

"""An HTTP (not HTTPS) and web-request vocabulary detector.

Write a strong negative value on HTTP/Http identifiers and namespaces.
Lowercase http is weaker when it introduces an ordinary prose link. Nearby
source syntax, quoting, comments, and link-introducing words distinguish these
uses. Related request names, web imports and HTTP letter fragments respond
more weakly. Two secondary source-code patterns are PHP namespace/variables
and jQuery's $. notation. Everything else is predicted as zero.
"""
import re

READS = ()
SOURCE = re.compile(
    r'\b(import|package|namespace|const|var|public|private|def|assert)\b|'
    r'\b(function|class)\s+\w+|:=|=>|->|[{};]|'
    r'\.(py|go|js|java|php|md)\b|[a-z]+[A-Z][a-z]+'
)
NETWORK = re.compile(
    r'\b(HTTP\w*|Http\w*|http\.[A-Za-z]+|ftp|tcp|Apache|server|client|'
    r'protocols?|requests?)\b'
)
LINK_INTRO = re.compile(
    r'\b(at|visit|see|here|links?|source|website|home\s?page)\W*$', re.I
)


def predict(token, before):
    text = token.strip()
    match = re.search(r'[A-Za-z]+', text)
    word = match[0] if match else ''
    lower = word.lower()
    punctuation = text[:match.start()] if match else text
    before = before.rsplit('<|endoftext|>', 1)[-1]
    code = bool(SOURCE.search(before))
    network = bool(NETWORK.search(before))
    adjoining = (not punctuation and not token[:1].isspace()
                 and before[-1:].isascii()
                 and before[-1:].isalpha())

    # In HttpSession the capital S starts a new word, not the secure protocol.
    if word.startswith(('https', 'HTTPS', 'Https')):
        return -0.15
    if lower.startswith('http'):
        suffix = lower[4:]
        if suffix:
            if suffix == 'client':
                return -3.2 if word[0].islower() else -4.4
            if suffix == 'status':
                return -0.7
            if suffix == 'response':
                return -2.0
            return -3.1
        if word == 'Http':
            return -11.5 if punctuation == '\\' else -6.4
        if word == 'HTTP':
            return -8.8 if adjoining else -6.1
        if punctuation == '.':
            direct_import = before.endswith(('org.apache', 'org.springframework'))
            return -11.6 if direct_import else -8.5
        if punctuation in ('/', '_', '-'):
            return -5.8
        if punctuation:
            return -6.0 if code or network else -1.8
        if not before:
            return -5.8
        if LINK_INTRO.search(before) or re.search(r'href=\\?["\']$', before):
            return -1.0
        if re.search(r'\b(import|require)\s*[("\' ]*$', before):
            return -6.5
        if adjoining:
            return -5.8 if code or network else -3.2
        if re.search(r'(?:^|\n)\s*(?:\d+\s*)?\*\s*$', before):
            return -3.0
        if before[-1:] in ('"', "'"):
            return -3.3
        if code or network:
            return -5.0
        return -1.0

    if lower in ('htt', 'ttp'):
        return -5.0
    if lower == 'ht':
        return -3.0 if punctuation == '.' else -0.3
    if lower == 'tp':
        return -2.1 if adjoining else -0.3
    if text == '.web' and 'springframework' in before:
        return -5.3 if before.endswith('.boot') else -6.4
    if lower == 'web':
        return -1.3 if adjoining and code else -0.6
    if text == '.annotation' and 'springframework' in before:
        return -4.8 if '.web.bind' in before[-30:] else -2.2
    if lower in ('request', 'requests'):
        if word in ('REQUEST', 'Requests'):
            return -0.2 if word == 'REQUEST' else 0.0
        if word[0].islower() and re.search(r'\bimport\s*$', before):
            return -6.5 if lower == 'requests' else -4.8
        if punctuation == '\\':
            return -3.5
        if before.endswith(('Http', 'HTTP')):
            return -2.5
        if word == 'Request' or punctuation or not token[:1].isspace():
            return -1.1
        return -0.85 if code or network else 0.02
    if lower == 'requestmapping':
        return -0.6 if punctuation == '.' else -1.8
    if lower == 'req':
        return -0.8
    if word == 'ajax':
        return -2.3
    if text == '$.' and re.search(r'function(?:\s+\w+)?\s*\(', before):
        return -5.7
    if text in ('$_', '($_'):
        return -3.4 if token[:1].isspace() or text.startswith('(') else -0.5
    if text == 'namespace' and re.search(r'<\?php\s*$', before):
        return -11.5
    if text == 'com' and re.search(r'\bpackage\s*$', before):
        return -2.0
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    value = predict(token, before)
    return (document, (before + token)[-240:]), value

"""A partial syntax-level approximation of this component.

Give document starts a negative offset. Contrast function/import/test syntax
(positive) with data access, type annotations, and UI state/handlers (negative).
Recent JavaScript and UI cues strengthen the latter responses. This intentionally
omits fine-grained lexical variation. Keep only 220 recent characters of state.
"""
import re

READS = ()

DATA_WORDS = {
    'data', 'value', 'values', 'row', 'node', 'element', 'item', 'items',
    'string', 'number', 'boolean', 'null', 'undefined', 'true', 'false',
}
TECHNICAL_START = DATA_WORDS | {
    'function', 'def', 'test', 'tests', 'loading', 'type', 'const', 'class',
    'user', 'assistant',
}
STATE_WORDS = {'selected', 'active', 'checked', 'disabled', 'visible', 'status'}
STATE_MEMBERS = {'.value', '.data', '.current', '.status'}
PRIMITIVE_TYPES = {'string', 'number', 'boolean', 'any', 'unknown'}
EVENT_FRAGMENTS = {'Click', 'Change', 'Focus', 'KeyDown', 'KeyPress',
                   'Blur', 'Submit'}

CODE = re.compile(
    r'\b(?:const|let|var)\b|function[ (]|=>|===|[{};]|'
    r'console\.|this\.|\.[jt]sx?\b'
)
JS = re.compile(
    r'\b(?:const|let|var|interface|export|async|await)\b|function[ (]|'
    r'=>|===|console\.|\.[jt]sx?\b|'
    r'\b(?:react|React|typescript|javascript)\b'
)
UI = re.compile(
    r'\b(?:React|react|props|state|useState|setState|onChange|handleChange)\b|'
    r'</?[A-Z]|\$scope'
)
EVENT = re.compile(r'^(?:on[A-Z]|handle[A-Z]|(?:get)?KeyDown|Focus)')
DOM_EVENT = r'(?:Click|Change|Input|Key|Focus|Blur|Mouse|Submit|Select)'

# Small, explicitly named programming punctuation conventions.
SYNTAX = {
    '=>': 0.36,          # arrow functions
    '?.': -1.06,        # optional chaining
    '.length': -0.65,   # collection size access
    '.test': 0.64,      # test methods / test-file names
    '::': -0.11,        # namespace separator
    '://': 0.23,        # URL scheme separator
    ':=': -0.16,        # short variable declaration
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    before = '' if first else carry[1]
    s = prefix.token_strings[-1]
    t = s.strip()
    identifier = t.lstrip('.(')
    last = before.rstrip()[-1:]
    recent = before[-200:]
    code = bool(CODE.search(recent))
    js = bool(JS.search(recent))
    ui = bool(UI.search(recent))

    value = SYNTAX.get(t, 0.0)
    if first:
        value -= 0.50 if any(c.isalpha() for c in t) else 0.27
        if identifier.lower() in TECHNICAL_START:
            value -= 0.79

    # Functions, imports, filenames and return-type punctuation.
    if t == '(function' or (t == 'function' and last and last in ',(:='):
        value += 1.04
    if t == 'import':
        value += 0.15
    if t in {'.js', '.jsx', '.ts', '.tsx'}:
        value += 0.19
    if js and t in {'):', '>):', '():'}:
        value += 0.41
    if js and t in {'\\', '\\\\'}:
        value += 0.17

    # Tests and array/data expressions.
    if t == '&&' and not re.search(r'cd |/testbed|/workspace', before[-100:]):
        value -= 0.39
    if js and t == '||':
        value -= 0.45
    if t in {'===', '!=='}:
        value -= 0.20
    if js and t == '[' and last and last in '=:':
        value -= 0.28
    if js and t.startswith('[]'):
        value -= 0.35
    if identifier.lower() in DATA_WORDS:
        value -= 0.09 * code + 0.25 * js
    if t in PRIMITIVE_TYPES and last and last in ':|<':
        value -= 0.51
    if js and t.startswith('(') and t[1:] in DATA_WORDS:
        value -= 0.20
    if t in STATE_MEMBERS:
        value -= 0.66
    if js and t in {"''", '""'}:
        value -= 0.79

    # UI callbacks and state vocabulary, including split identifier fragments.
    if code or js:
        if EVENT.match(identifier):
            value -= 0.53
        if re.match(r'^(?:on|handle)' + DOM_EVENT, identifier):
            value -= 0.75
        if re.match(r'^handle' + DOM_EVENT, identifier):
            value -= 1.63
        if t in EVENT_FRAGMENTS:
            value -= 0.74
    if identifier.lower() in {'loading', 'isloading'}:
        value -= 0.87 + 1.24 * code + 1.28 * ui
    if js:
        if t in {'set', 'SET', '_SET'}:
            value -= 0.85
        if t in {'handle', 'Handle'}:
            value -= 0.64
        if identifier.lower() in STATE_WORDS:
            value -= 0.41
        if re.match(r'^\.?set[A-Z_]', t):
            value -= 0.56

    return (doc, (before + s)[-220:]), float(value)

