            value = 6.5 if last in NAME_PREFIXES else 14.7
        elif token == '格':
            value = 8.9
            if last and last in NAME_PREFIXES:
                value = 2.7
            elif last and last in '价價価资資严嚴厳':
                value = 4.5
            elif previous.endswith(('单元', '單元', '窗')):
                value = 2.4  # spreadsheet cell or window pane
            elif previous.endswith(('九宫', '九宮', '部落')):
