            elif last == '空':
                value = 4.9  # a space character
            elif last == '格':
                value = 12.5  # repeated 格, as in the title 格格
        elif token in ('规格', '規格'):
            value = 5.7
        elif token in ('合格', '品格', '网格', '網格'):
            value = 4.0
        elif token in ('资格', '資格'):
            value = 3.2
        elif token == '人格':
            value = 6.3
        elif token in ('严格', '嚴格', '严格的', '格外'):
            value = 1.2
        elif token in ('格式', '格局', '风格', '風格',
                       '性格', '的性格', '表格'):
            value = 2.1
        elif token == '不合格':
            value = 1.7
        # Other fused names, prices, and longer phrases are weak.
    elif '隔' in text:
        if fragment:
            value = 7.0
        elif token == '隔':
            value = 4.8
        elif token in ('间隔', '間隔', '每隔'):
            value = 2.8
        elif token in ('时隔', '時隔', '隔着', '隔著', '隔离', '隔離'):
