import regex as re

READS = ()

# Simplified, traditional, and Japanese spellings of these character families.
CHARACTERS = {
    '还': -5.7, '還': -5.4,             # still / return
    '换': -2.6, '換': -1.6,             # exchange
    '坏': -4.1, '壞': -4.4, '壊': -1.8, # broken
    '环': -1.4, '環': -2.0,             # ring
    '焕': -2.9,                         # shine (same phonetic as 换)
}
WORDS = {
    '还款': -5.0, '偿还': -3.9, '还原': -3.6,
    '坏了': -1.8, '换了': -2.0,
    '还不': -1.0, '还在': -0.85, '还可以': -0.5,
    '不仅': -1.2, '而且': -0.6, '优惠': -1.2, '返': -0.8,
    'còn': -3.0, 'hoàn': -4.0,
}
BREAKS = set('，,、；;：:。.!！?？\n“「"')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous = b'', ''
        first = True
    else:
        _, tail, previous = carry
        first = False
    raw = prefix.token_bytes[-1]
    text = prefix.token_strings[-1].strip()
    joined = tail + raw
    value = 0.0
    if first and text.isascii():
        if raw.startswith(b' ') and text.isalpha() and text.islower():
            value = 0.19
        elif text.isdigit():
            value = -0.08
    if '\ufffd' in text:
        character = joined.decode('utf-8', 'replace')[-1:]
        if character == '还':
            value = -8.1
        elif character == '還':
            value = -0.5
        elif character == '환':
            value = -10.1
        elif character in ('环', '環'):
            value = -3.0
        else:
            value = CHARACTERS.get(character, 0.0)
    elif text in CHARACTERS:
        value = CHARACTERS[text]
        if text in ('还', '還', '换', '換') and previous[-1:] in BREAKS:
            value -= 0.9
        if text == '還' and re.search(r'[\p{Hiragana}\p{Katakana}]',
                                          tail.decode('utf-8', 'replace')):
            value = -7.7
    elif text == '元' and previous.endswith('還'):
        value = -5.2
    elif text in WORDS:
        value = WORDS[text]
    elif text.endswith(('还', '還')):
        value = -5.0
    elif text.startswith(('还', '還')):
        value = -0.15
    if re.search(r'(?:^|[^A-Za-z])Khan\Z', joined.decode('utf-8', 'replace'), re.I):
        value = 1.7
    return (doc, joined[-24:], prefix.token_strings[-1]), value

