"""A coarse document-opening and formatting heuristic.

Ordinary text gets a near-zero background. At document starts, digits,
line breaks, subject pronouns, imports and definitions are more positive.
Large special cases include SELECT, region markers, NUL, the end-of-text
marker, the fragment `Am`, and YAML front matter. YAML keys and colons
remain positive, especially the opening `title:`. Middle-dot runs and
forum "Replies Latest reply" headers are negative; equals/colon dividers
are positive. State resets at document boundaries. This approximates
observed motifs, not the component's substantial fine lexical variation.
"""

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, yaml, line, recent = 0, False, '', ''
    else:
        _, position, yaml, line, recent = carry
    value = 0.002
    if position == 0:
        value = 0.10
        if text.isdigit():
            value = 0.23
        elif text.isspace() and '\n' in text:
            value = 0.36
        elif text.lower() in {'i', 'we', 'you', 'he', 'she', 'it', 'they'}:
            value = 0.46
        elif text in {'import', 'from', 'using'}:
            value = 0.76
        elif text in {'def', 'export'}:
            value = 1.06
        if text == '<|endoftext|>':
            value = 2.16
        elif '\x00' in text:
            value = 2.42
        elif text.lower() == 'select':
            value = 1.52
        elif text == 'Am':
            value = 1.61
        elif text == '#region':
            value = 1.73
        elif text == '#pragma':
            value = 0.62
        elif text.strip() in ('"""', "'''"):
            value = 0.74
        elif text.strip() == '---':
            value, yaml = 0.89, True

    if yaml and position > 0:
        if text.strip() == '---':
            yaml = False
        elif position == 1 and text == 'title':
            value = 0.49
        elif position == 2 and text == ':' and line == 'title':
            value = 1.02
        elif text.startswith(':') and line.strip().isidentifier():
            value = 0.23
        elif (not line or line.isidentifier()) and text.isidentifier():
            value = 0.15

    stripped = text.strip()
    if stripped and not stripped.strip('·') and len(stripped) >= 2:
        value = -0.39
    elif stripped and not stripped.strip('=') and len(stripped) >= 2:
        value = min(0.24, 0.014 * len(stripped) + 0.025)
    if (text.count(':') >= 6 and
            all(c in ': \t' for c in text)):
        value = 0.90
    if position < 12 and text == ' reply' and recent.endswith('Replies Latest'):
        value = -1.14

    line = (line + text).split('\n')[-1][-80:]
    recent = (recent + text)[-50:]
    return (doc, position + 1, yaml, line, recent), value

"""Sparse approximation using position, Chinese constructions, and notation.

Most initial token classes get positive baselines, grouped by script and case.
Chinese mental/evaluative predicates get small negative adjustments, enlarged
by manner/how modifiers. Selected action verbs + 好 ('well') are negative.
Adverbial 地 and a few notation/heading delimiters have separate rules.
These rules describe selected responses, not all of the context dependence.
"""
import re
from functools import lru_cache
import cedict
import regex

READS = ()

MENTAL_ACTIONS = (
    'to know', 'to recognize', 'to comprehend', 'to understand',
    'to investigate', 'to research', 'to evaluate', 'to assess',
    'to handle', 'to face', 'to confront', 'to take note of',
    'to pay attention', 'to be good at', 'to be adept at',
)
ORGANIZING_ACTIONS = (
    'to implement', 'to carry out', 'to launch', 'to develop',
    'to display', 'to exhibit', 'to grasp', 'to grab', 'to arrange', 'to plan',
    'to exploit', 'to utilize', 'to make use of', 'to disseminate',
    'to speak', 'to explain',
)
MANNER = frozenset('认真 正确 深刻 深入 切实 充分 高度 精心 重新 坚决 '
                   '积极 进一步 真正 严格 紧密 相应 特别'.split())
HOW = frozenset('如何 怎么 怎样 怎麼 如何才能'.split())

@lru_cache(maxsize=32768)
def senses(word):
    g = cedict.glosses(word)
    if not g and len(word) > 1 and word[-1] in '到了着过':
        g = cedict.glosses(word[:-1])
    if not g and len(word) > 1 and word[0] in '来去':
        g = cedict.glosses(word[1:])
    return g


def matches(word, meanings):
    return any(g.startswith(m) for g in senses(word) for m in meanings)


def initial_value(word):
    """A coarse first-token baseline; classes, not individual token identities."""
    if not word:
        return 0.16
    if word.startswith('<|'):
        return -0.026
    if re.fullmatch('[A-Z]+', word):
        return 0.31
    if re.fullmatch('[A-Z][a-z]+', word):
        return 0.235
    if re.fullmatch('[a-z]+', word):
        return 0.175
    if re.fullmatch('[0-9]+', word):
        return 0.21
    if regex.search(r'\p{Script=Han}', word):
        return 0.14
    return 0.1 if word.isascii() else 0.04


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, recent, in_tag, position = '', '', False, 0
    else:
        _, previous, recent, in_tag, position = carry
    raw = prefix.token_strings[-1]
    word = raw.strip()
    value = initial_value(word) if position == 0 else -0.001
    if regex.fullmatch(r'\p{Script=Han}+', word):
        if matches(word, MENTAL_ACTIONS):
            value -= 0.02
            if previous in MANNER or previous in HOW:
                value = -0.6
            elif (matches(word, ('to research',))
                  and matches(previous, ('to investigate',))):
                value = -0.8
        if word == '好' and matches(previous, ORGANIZING_ACTIONS):
            value = -1.2
        elif (len(word) > 1 and word.endswith('好')
              and matches(word[:-1], ORGANIZING_ACTIONS)):
            value = -0.9
        if word == '地':
            value = -0.075 if previous not in MANNER else -0.55
    # A greater-than sign outside an angle-bracket tag in Chinese prose.
    if word in {'>', '≥'} and not in_tag and '\n' not in raw:
        if regex.search(r'\p{Script=Han}', recent):
            value = 0.6 if raw == word else 0.3
    if word == '%' and regex.search(r'\p{Script=Han}', recent):
        if re.search(r'\d$', recent):
            value = 0.38
    if word in {'>', '≥'} and not in_tag and value == -0.001:
        if re.search(r'(?:\d|\b[A-Za-z]|\$)\s*$', recent):
            if not any(c in recent for c in '{};'):
                value = 0.1
    if len(word) >= 2 and set(word) == {'·'}:
        value = 0.38
    if word == ':' and previous == 'Title' and position == 1:
        value = -2.564
    for char in raw:
        if char == '<':
            in_tag = True
        elif char == '>':
            in_tag = False
    recent = (recent + raw)[-48:]
    return (doc, word, recent, in_tag, position + 1), float(value)

"""Approximate this component with short-range lexical and spelling rules.

Electrical-part words and several i-initial endings get negative values;
some o/u continuations of o-plus-consonant stems get positive ones.  There
are also explicit GitHub-domain, filename, and document-title rules.
Constants are fitted from training text. Unmatched text gets zero: this is a partial
account, not a general semantic classifier. Keep 80 characters of local
history and reset it whenever the document changes.
"""
import re

READS = ()


def activation(old, previous, token):
    low = token.lower()
    m = re.search(r'[^\W\d_]+$', old, re.UNICODE)
    stem = m.group().lower() if m else ''
    word = stem + low if low.isalpha() else low.strip()

    if old == 'Title' and token == ':':
        return 3.88
    if low == '.com' and old.lower().endswith('github'):
        return 1.262
    # Chinese/Japanese conductor or window-body endings; Chinese chip/core.
    if token in ('体', '體') and old.endswith(('导', '導')):
        return -4.377
    if token in ('体', '體') and old.endswith('窗'):
        return -1.878
    if token == '芯':
        return -3.98
    if low == 'ors' and stem.endswith(('conduct', 'connect')):
        return -3.975
    for root in ('conductor', 'connector', 'insulator'):
        if root in word and root not in stem:
            return {'conductor': -2.477, 'connector': -1.807,
                    'insulator': -2.02}[root]
    if word.endswith('semiconduct') and not stem.endswith('semiconduct'):
        return -2.459
    if low.strip() == 'silicon':
        return -0.33
    if low.startswith(' nit') and stem == 'silicon':
        return -1.501
    # Typical uppercase repository filenames: CONTRIBUTING and CONDUCT.
    if token == 'TR' and previous == 'CON':
        return -1.688
    if token == 'DUCT' and previous.endswith('CON'):
        return -1.802
    if low.startswith('it') and stem.endswith('qisk'):
        return -1.323
    if low == 'it' and stem.endswith(('constit', 'const')):
        return -2.381
    if low == 'ит' and stem.endswith('конст'):
        return -2.381
    # Cyrillic cosmonaut/coronavirus and Latin kon-u continuations.
    if low == 'ав' and stem.endswith(('мон', 'рон')):
        return 5.066
    if low.startswith('u') and previous == ' kon':
        return 4.352
    if low.startswith('i') and stem.endswith(('convey', 'coinc')):
        return -0.867
    if low == 'ors' and stem.endswith('convey'):
        return -0.867
    if low.startswith('itor') and stem.endswith(('progen', 'repos', 'mon')):
        return -1.218
    # Rounded/nasal stem endings followed by contrasting vowel suffixes.
    rounded = bool(re.search(r'o(?:n+|m+|s+|k+|c+|rn)$|kn$', stem))
    if not token[:1].isspace():
        if stem.endswith(('on', 'sk')) and low in ('ite', 'ites', 'ita'):
            return -2.734
        if low in ('it', 'its', 'ited', 'ides', 'ided', 'is', 'io', 'itr'):
            if re.search(r'on$|[ck]om$|pos$|ens$|[ckg]n$|isk$|conf$', stem):
                return -0.958
        if rounded and low in ('ia', 'icia', 'oni', 'onia'):
            return -0.746
        if rounded and low in ('omo', 'oma'):
            return 1.502
        if rounded and re.fullmatch(r'u[smcnyel]*|o[scnmgpl]+', low):
            return 0.495
        if stem.endswith('cons') and low in ('ular', 'uls'):
            return 1.206
        if stem.endswith('con'):
            if low.startswith('clu'):
                return 0.581
            if low.startswith('ferenc'):
                return 0.561
            if low == 'sum':
                return 1.206
            if low.startswith('com'):
                return 1.863
        if stem.endswith(('cons', 'cos', 'cosm', 'ont', 'on')):
            if low in ('ology', 'ological', 'ographic', 'ography', 'ically'):
                return 0.439
    if previous.lower().endswith('com') and low == 'unque':
        return 2.389
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    old, previous = ('', '') if first else carry[1:]
    token = prefix.token_strings[-1]
    value = activation(old, previous, token)
    return (doc, (old + token)[-80:], token), value

"""Heuristic for the short syllable 'so', rather than every word containing it.

The English word is strongest after a copula or pronoun, weaker after a
comma, coordinator, or in 'do so'/'if so'. Initial-capital So is weaker.
Also recognize short so/zo/iso fragments, including an o-fragment after
s/z/x in the preceding token. Transliteration extends this spelling rule
across scripts. German-looking neighbors damp the English-word response.
Japanese, Korean, Scandinavian, and Cyrillic so forms have separate levels;
related connectives receive small responses. Most other tokens receive zero.
Whole words such as 'also' are not treated as fragments.
"""
import re
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
COPULAS = {'am', 'is', 'are', 'was', 'were', 'be', 'been', 'being',
           "'s", "'re", "'m"}
COORDINATORS = {'and', 'or', 'but', 'und', 'even'}
PRONOUNS = {'i', 'you', 'he', 'she', 'it', 'we', 'they',
            'me', 'him', 'her', 'us', 'them'}


def response(t, previous):
    raw = t.strip()
    word = anyascii(raw)
    p = anyascii(previous.strip())
    pl = p.lower()
    if raw in {'ソ', 'そ'}:
        return 3.4  # Japanese so syllables
    if raw == '소':
        return 1.5  # Korean so syllable
    if raw == 'så':
        return 3.7  # Scandinavian so
    if raw.lower() == 'со':
        return 0.7
    if word.lower() == 'also':
        return 0.0
    if not raw.isascii() and word.lower() == 'so':
        return 0.0
    word = word.strip('._-/')
    if word == 'so' and t.startswith(' '):
        if not p:
            return 1.6
        if any(mark in p for mark in ',;:'):
            return 0.75
        if pl in COPULAS:
            return 6.6
        if zipf_frequency(pl, 'de') > max(4, zipf_frequency(pl, 'en') + 0.6):
            return 2.2
        if pl == 'if':
            return 0.3
        if pl in COORDINATORS:
            return 1.2
        if pl in {'do', 'does', 'did', 'doing', 'done'}:
            return 2.3
        if pl in PRONOUNS:
            return 6.6
        if p[-1].isdigit():
            return 2.4
        if not p[-1].isalnum():
            return 1.6
        return 4.5
    if word == 'So':
        return 0.5
    if word == 'SO':
        return 3.4 if t.startswith(' ') else 6.1
    if word == 'so':
        return 2.3 if pl.endswith(('s', 'z')) else 2.0
    if word.lower() == 'iso':
        return 8.1 if word.isupper() else 5.2 if t.startswith(' ') else 4.1
    if word.lower().startswith('iso') and len(word) == 4:
        return 0.7
