        return 2.8 if word.lower() == 'zo' else 0.75
    if re.fullmatch(r'[sSzZ]o[^aeiou]', word):
        return 0.1 if word[-1].lower() == 'n' else 0.6
    if 'ので' in t:
        return 0.5
    if 'そう' in t:
        return 0.2
    if word.lower() in {'such', 'thus', 'therefore', 'hence'}:
        return 0.2
    if (not t[:1].isspace() and word and word[0].lower() == 'o'
            and pl.endswith(('s', 'z', 'x'))):
        if word == 'O' and p.endswith('S'):
            return 4.6
        if len(word) == 1:
            return 2.1
        if word.lower().startswith(('or', 'on')):
            return 0.2
        return 1.5 if len(word) == 2 else 0.5
    if word == '0' and pl.endswith('s'):
        return 1.5
    return 0.0


def step(carry, prefix, upstream):
    same = (len(prefix.document_ids) > 1 and
