"""A sparse, boundary-sensitive surface-pattern approximation.

Strong responses belong to particular source-text openers, control characters,
and short initial sequences. Moderate boundary effects are approximated using
English articles/copulas, digits, and underscore-prefixed identifiers. Repeating
an initial token retains its boundary prediction. Ordinary lexical fluctuations
are not modeled; this is not a general semantic detector.
"""

READS = ()


def initial_value(token):
    """Recognizable classes at the beginning of a document or initial run."""
    if token == '\x00':
        return 2.667
    if token == '\r':
        return -1.398
    if token == '^^^^':
        return -1.762
    if token == '//\n':
        return -2.403
    if token == '<|endoftext|>':
        return -1.0
    if token == '<|im_start|>':
        return -0.371
    if token == 'assistant':
        return -0.741
    if token == '<a':
        return 1.879
    if token == '..':
        return 1.305
    if token.strip() in {'<', '>'}:
        return 1.25 if token.startswith(' ') else 0.81
    if token == 'namespace':
        return 1.869
    if token in {'package', '#include'}:
        return 0.75
    if token.rstrip('\r\n') in {'/*', '/**'}:
        if token == '/*' or token.endswith('\n'):
            return 0.70

    word = token.strip().lower()
    if word in {'a', 'an', 'the'}:
        return 0.46 if word == 'an' else -0.25
    if word in {'is', 'are', 'was', 'were'}:
        return -0.34
    if len(token) == 1 and token.isascii() and token.isdigit():
        return -0.15
    if token.startswith('_') and token.lstrip('_').isalnum():
        return -0.37
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, first, initial_run, tail = 0, token, True, ''
    else:
        _, position, first, initial_run, tail = carry
        initial_run = initial_run and token == first

    value = initial_value(token) if initial_run else 0.0
    if position == 1:
        if tail == '{' and token == '[':
            value = -2.07
        elif tail == '1' and token == '2':
            value = -2.168
    elif position == 2 and tail == '12' and token == '2':
        value = -0.641

