import re

READS = ()
WORD = re.compile(r'([^\W\d_]+)\Z')
MATH = re.compile(
    r'\b(integer|integers|number|numbers|prime|primes|divis\w*|'
    r'factor\w*|sum|product|mod|odd|even|multiply)\b|[=+×²]'
)
OF_RELATIONS = {
    'multiple': -6.0, 'multiples': -4.8,
    'divisor': -2.5, 'divisors': -4.1,
    'factor': -0.65, 'factors': -2.8,
    'partitions': -2.1, 'powers': -2.6,
    'reciprocal': -1.5, 'digit': -2.0, 'digits': -1.8,
}
# Inflected translations of number/count, and stems exposed by token splitting.
NUMBER_WORDS = set('''
    numero numeri número números numeros số чис число числа чисел числу
    liczba liczby liczb liczbę liczbą čís číslo szám număr
    cifra cifre cifras chiffre chiffres dígito dígitos
'''.split())


def response(token, before, previous):
    text = before + token
    m = WORD.search(text)
    word = m.group(1) if m else ''
    w = word.lower()
    prior = text[:m.start()].rstrip() if m else before.rstrip()
    pm = WORD.search(prior)
    last = pm.group(1).lower() if pm else previous.strip().lower()

    if w == 'of':
        if last == 'power':
            if prior.lower().endswith('to the power'):
                return 0.3
            integer_power = re.search(
                r'\b(a|largest|smallest) power\Z', prior.lower()
            )
            return -4.2 if integer_power else -0.1
        return OF_RELATIONS.get(last, 0.0)
    if w == 'by':
        if last in {'divisible', 'divisibility'}:
            return -5.7
        if last in {'divide', 'divides', 'dividing', 'division'}:
            return -2.0
        return -0.65 if last in {'divided', 'multiply', 'multiplied'} else 0.0
    if w == 'to' and re.search(r'\bfrom\s+1\s*\Z', before.lower()):
        return -2.8
    if w in {'integer', 'integers'}:
        if last in {'positive', 'negative', 'signed', 'unsigned', 'consecutive', 'odd'}:
            return -4.3
        if last in {'an', 'is', 'are', 'be', 'not'}:
            return -3.2
        if word[0].isupper():
            return -1.2
        return -3.2 if w == 'integers' else -2.2
    if w in {'number', 'numbers'}:
        if last in {'natural', 'whole'}:
            return -5.3 if last == 'natural' else -3.9
        if last in {'prime', 'composite', 'binary', 'fibonacci', 'triangular'}:
            return -3.0
        if last in {'real', 'rational', 'complex', 'odd', 'even', 'negative'}:
            return -1.9
        if last in {'a', 'any', 'each', 'one', 'two', 'these', 'of'}:
            return -1.7
        if last in {'line', 'phone', 'account', 'accession', 'stirling'}:
            return 0.0
        if word[0].isupper() or not token[:1].isspace():
            return -0.65
        return -1.25 if w == 'numbers' else -0.85
    if w in {'coprime', 'collatz', 'primality'}:
        return -2.5 if w == 'primality' else -4.0
    if w in {'prime', 'primes'}:
        if prior.endswith('\\'):
            return 1.6
        if prior.endswith(('non-', 'co-')):
            return -3.7
        if last == 'not' or prior.endswith('_'):
            return -2.4
        if last == 'the' and w == 'prime':
            return -0.2
        return -1.8 if w == 'primes' else -1.0
    if w in {'square', 'squares', 'cube', 'cubes'}:
        if last == 'perfect':
            return -4.1
        return 1.5 if last == 'chi' else -0.15
    if w in {'multiple', 'multiples'}:
        if last in {'a', 'any', 'minimal', 'next', 'another', 'rational'}:
            return -1.8
        return -1.45 if w == 'multiples' else 0.0
    if w in {'divisible', 'divisibility', 'multiset', 'multisets'}:
        return -1.5
    if w == 'factorial':
        return -2.0 if token.strip().lower() != w else 0.0
    if w in {'digit', 'digits', 'fraction', 'fractions', 'decimal', 'decimals'}:
        return -0.45
    if w in {'even', 'odd', 'natural', 'whole'}:
        return -0.8 if MATH.search(before.lower()) else 0.0

    # Programming type names and conversion expressions.
    if token.endswith(('Int', 'Integer')):
        if 'random' in w:
            return -3.0
        if 'big' in w or last == 'big':
            return -3.5
        return -0.4
    if w in {'bigint', 'tinyint'}:
        return -2.8
    if w in {'int', 'str'}:
        if prior.endswith('\\') and w == 'int':
            return 0.6
        p = previous.strip()
        if p in {'=', '+=', '->', '=='}:
            return -2.8 if w == 'int' else -2.2
        if p == '+' and w == 'str':
            return -3.0
        if p.endswith(':'):
            return -2.7 if w == 'int' else -1.1
        if prior.endswith(('[', '[]')):
            return -2.6 if w == 'int' else -1.9
        return -1.25 if prior.endswith(('(', '`', '&', '/')) else -0.65
    if w in NUMBER_WORDS:
        return -3.3 if w.startswith('чис') else -2.7
    if w.endswith(('zahl', 'zahlen', 'getal', 'getallen')):
        return -2.0
    if w in {'nombre', 'nombres'} and word.islower():
        if w == 'nombres' or last in {'un', 'le', 'ce', 'du', 'grand', 'large', 'de'}:
            return -4.0
    if token in {' 수', '수'}:
        return -1.55 if token.startswith(' ') else -0.6
    if token.endswith('数'):
        return -0.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before, previous = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    value = response(token, before, previous)
    return (doc, (before + token)[-120:], token), value

