"""Whole-number words detector for layers.1.mlp.down_proj component 4657.

What it does: this component writes a mostly negative value at tokens that name whole
numbers or count-like quantities. Its activation is strongly negative on "integers" and
Collatz/prime-style number-theory words, moderately negative on "integer", "number(s)" and
their translations, and weakly negative on type names such as int, str and float, most
strongly when those are used in code (after "+", "=", ":" or "("). It is also strongly
negative on "of" / "by" / "to" right after "multiple", "factors" or "divisible", the
divisibility phrases ("multiple of 3", "factors of 12"). Everything else is about zero.

The program is a word list with three tiers and two small context rules. It has no state
(the carry is unused), and it reads only the newest token and the one before it.
"""

READS = ()

# Tier 1: plural and number-theory words that drive the response most.
STRONG = {"integers", "egers", "nombres", "atz", "divisible", "_prime", "primes", "imes", "zahl"}

# Tier 2: the words for "integer" and "number", in English and other languages.
MEDIUM = {"integer", "number", "numbers", "numero", "nombre", "números", "número", "數",
          "数字", "수"}

# Tier 3: type and code names for numbers (int, str, float), and number stems.
WEAK = {"int", "_int", "(int", "[int", "str", "(str", "num", "_num", "float", "(float",
        "数", "umber"}

# Context rules.
PHRASE_HEADS = {"multiple", "multiples", "factor", "factors", "divisible", "divide",
                "divided", "power", "powers"}
LINKS = {"of", "by", "to"}
CODE_BEFORE = {"+", "+=", "=", ":", "(", "return"}
ARTICLES = {"a", "an", "any", "positive", "natural", "whole", "even", "negative"}


def step(carry, prefix, upstream):
    """Activation at the newest token, from its word and the word before it."""
    word = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    value = 0.0
    if word in STRONG:
        value = -2.5
    elif word in MEDIUM:
        value = -1.5 if prev in ARTICLES else -0.8
    elif word in WEAK:
        value = -0.6
        if prev in CODE_BEFORE:
            value -= 1.5
    elif word in LINKS and prev in PHRASE_HEADS:
        value = -3.0 if prev.startswith(("multiple", "factor")) else -1.5
    return carry, value

