"""Approximate a sparse collection of local written constructions.

The strongest negative rule is an unspaced dash after a short Latin-capital
abbreviation. Longer words and lowercase fragments get smaller pulses.
Spaces after month/numbered-item abbreviations and 'as if/as though' are
positive; 'what if' is negative. Related 'as' phrases, slash/ampersand after
capitals, initial heading colons, and double middle dots have small rules.
Unmatched positions are zero. The text tail and age reset at each document.
"""
import calendar
import re

READS = ()
MONTHS = frozenset(calendar.month_abbr[1:]) | {'Sept'}
WEEKDAYS = frozenset(calendar.day_abbr)
# Abbreviations introducing figure, exercise, number, volume, and page numbers.
NUMBER_LABELS = {'Fig': 5.4, 'Ex': 7.0, 'No': 2.5, 'vol': 2.1, 'pp': 1.0}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, age = '', 0
    else:
        _, tail, age = carry
    t = prefix.token_strings[-1]
    same = prefix.position > 0 and prefix.document_ids[-2] == doc
    previous = prefix.token_strings[-2] if same else ''
    word = previous.strip()
    value = 0.0

    if t == ' ' and word in MONTHS:
        if word == 'May':
            value = 0.9
        elif word in {'Apr', 'Sept'}:
            value = 2.2
        else:
            value = 3.7
        parts = tail.split()
        if len(parts) > 1 and parts[-2].rstrip('.') in WEEKDAYS:
            value += 2.3
    elif t == ' ' and word in NUMBER_LABELS:
        value = NUMBER_LABELS[word]
    elif t in (' if', ' though', ' soon', ' of', '-if'):
        if word.lower() == 'as':
            value = {' if': 5.3, ' though': 4.1,
                     ' soon': 1.1, ' of': 0.7}.get(t, 0.0)
        elif word.lower().strip('"') == 'what' and t in (' if', '-if'):
            value = -5.7 if t == ' if' else -3.4
    elif t in ('-', '‐', '–') and not previous.endswith((' ', '\n', '\t')):
        m = re.search(r'[A-Za-z0-9]+$', tail)
        whole = m[0] if m else ''
        word = word.lstrip('/-')
        if word.isascii() and word.isalpha():
            if word.isupper():
                if len(word) <= 2:
                    value = -5.5 if len(whole) <= 2 else -3.0
                    if any(c.isdigit() for c in whole):
                        value = -2.0
                    elif len(whole) == 1 and not previous.startswith(' '):
                        value = -3.4
                else:
                    value = -1.8 if len(word) == 3 else -0.7
            elif len(whole) <= 3:
                value = -1.3 if len(whole) == 2 else -0.6
            else:
                value = -0.2 if len(word) <= 4 else 0.0
        if t == '‐':
            value *= 0.75
    elif t in ('/', '&') and word.isascii() and word.isupper():
        value = -0.9 if t == '/' else -3.2
    elif t == '··':
        value = 2.85
    elif age == 1 and word == 'Title' and t == ':':
        value = 7.4
    elif age == 1 and word == 'Q' and t in (':', ':\n\n'):
        value = 1.12 if t == ':' else 3.3

    return (doc, (tail + t)[-80:], age + 1), value

