"""Layer-1 MLP down_proj, component 4658: a rare, polysemantic feature.

It is silent on almost every token. Each rule below looks at the current token and the one
before it, and the values are typical activations seen in text.

- Negative on a dash that follows a short all-caps code, strongest when the code starts a
  word: P-51, SF-15, GS-07, B-29 (about -5.5; -3 when the code is glued to the word before).
  Weaker negatives: a dash after a longer caps word (-1) or a short lowercase code such as
  rb-1 or ki-67 (-0.7); an ampersand after a short caps code (D&AD, -3).
- Negative on the 'if' of 'what if' (-5).
- Positive on 'if' or 'though' after 'as' (as if, as though): about +5.
- Positive on the space after an abbreviated month, before the day or year (Jan 17,
  Sep 01): about +3.5, about +2 after 'Apr'. Also after 'Fig' and 'No' (about +4.5).
- Positive on the colon of a 'Title:' line and on the 'Q:' line break of a 'Q:' line, when
  either opens a document (<|endoftext|> then Title: gives +7.4; Q:\\n\\n gives +3.3).

Everything else predicts 0.
"""
READS = ()

MONTHS = {"Jan", "Feb", "Mar", "Jun", "Jul", "Aug", "Sep", "Sept", "Oct", "Nov", "Dec"}
LABELS = {"Fig", "No"}
DASHES = {"-", "‐", "‑", "–"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    prev = toks[-2] if len(toks) > 1 else ""
    before = toks[-3] if len(toks) > 2 else ""
    word = prev.strip()
    caps_code = word.isupper() and word.isalpha() and len(word) <= 2
    if cur in DASHES:
        if caps_code:
            return None, (-5.5 if prev.startswith(" ") else -3.0)
        if word.isupper() and word.isalpha():
            return None, -1.0
        if word.islower() and word.isalpha() and len(word) <= 3:
            return None, -0.7
    if cur == "&" and caps_code:
        return None, -3.0
    if cur in (" if", " though"):
        if word.lower().lstrip("\"“") == "as":
            return None, 5.0
        if word.lower().lstrip("\"“") == "what" and cur == " if":
            return None, -5.0
    if cur == " ":
        if word == "Apr":
            return None, 2.0
        if word in MONTHS:
            return None, 3.5
        if word in LABELS:
            return None, 4.5
    if cur == ":" and prev == "Title" and before == "<|endoftext|>":
        return None, 7.4
    if cur == ":\n\n" and prev == "Q" and before == "<|endoftext|>":
        return None, 3.3
    return None, 0.0

