"""A sparse response to written 'bh', especially at token boundaries.

Devanagari and Gurmukhi BHA fragments are treated as the same consonant.
response can persist into the next word fragment.  Cyrillic b-consonant
clusters have a separate, mostly negative response.  Smaller rules cover
bj/hj, middle-dot leaders and three document-opening tokens. Unstructured
activations are replaced by a constant rather than a token lookup table.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, b'', '', None)
    _, tail, previous, recent = carry
    raw = prefix.token_bytes[-1]
    token = prefix.token_strings[-1]
    low = token.lower()
    before = tail.decode('utf-8', 'replace')
    joined = (tail + raw).decode('utf-8', 'replace')
    value, event = 0.002, None
    split = (before.lower().endswith(('b', 'б'))
             and low.startswith(('h', 'х')))
    match = re.search(r'(bh|Bh|BH|бх)([^\W\d_]{0,2})$', token)
    if split:
        word = re.search(r'[^\W\d_]+$', before)
        word = word.group().lower() if word else ''
        rest = low[1:]
        value = 3.5
        if len(word) == 1:
            value += 4.0 + (2.0 if not rest else 0.0)
        elif word[-2:-1] == 'a':
            value += 3.0
        elif word[-2:-1] in ('e', 'i'):
            value -= 1.0
        if rest.startswith('a'):
            value += 2.0
            if rest.endswith(('m', 'b', 'd')):
                value -= 2.0
            elif rest.endswith('r'):
                value += 1.0
        if token.startswith('H'):
            value = value * 0.45 if rest else value + 2.0
        event = (len(rest), value)
    elif match:
        cluster, rest = match.groups()
        value = {'bh': 3.8, 'Bh': 6.5, 'BH': 2.7, 'бх': 5.0}[cluster]
        if rest:
            value *= 0.75
        event = (len(rest), value)
    elif recent is not None and token[:1].isalpha():
        distance, strength = recent
        decay = 0.6 if distance == 0 else 0.4
        value = strength * decay if low[0] in 'aeiouäöüâî' else 0.5

    if low.strip() == 'bj':
        value = 0.7 if token[:1].isspace() else 2.4
    elif before.lower().endswith('b') and low.startswith('j'):
        value = 3.5
    elif low.strip() == 'hj':
        value = 1.1
    if before.lower().endswith('б'):
        if low.startswith(('щ', 'ж')):
            value = -2.7
        elif low.startswith('н'):
            strong = (previous.strip().lower() == 'об'
                      or before.lower().endswith('еб'))
            value = -2.0 if strong else -0.3
        elif low.startswith('лаг'):
            value = 1.7

    # Decode joined bytes so a letter split across tokens still counts.
    if joined.endswith(('भ', 'ਭ')) and not before.endswith(('भ', 'ਭ')):
        value = 6.8
    elif before.endswith(('भ', 'ਭ')) and raw in (b'\xe0\xa8', b'\xe0\xa5'):
        value = 6.1
    if joined.endswith('ਭਾ'):
        value = 14.0
    elif before.endswith('ਭਾ') and token[:1].isalpha():
        value = 10.0
    elif 'ਭ' in before[-3:] or 'भ' in before[-3:]:
        if (raw and 0x80 <= raw[0] <= 0xBF) or token.startswith('्'):
            value = 3.8

    if token and set(token) == {'·'} and len(token) >= 2:
        value = -1.65
    if not before:
        if token == 'from':
            value = 2.07  # Python import at the start of a document.
        elif token == 'int':
            value = -1.66
        elif token == '<|endoftext|>':
            value = -2.11
    return (doc, (tail + raw)[-30:], token, event), float(value)

"""A spelling-based approximation to a sparse positive activation.

Training firings cluster around tech, tel, tek and talk, especially when a
short token completes the spelling after a preceding t/te fragment. Whole
