    value = 0.0
    if w == 'tech':
        value = 3.0 if s.startswith('-') else (4.2 if s[0].isspace() else 5.8)
    elif w.endswith('tech'):
        value = 3.0
    elif w.startswith('tech'):
        value = 0.2
    elif w == 'tel':
        value = 4.0
    elif w.startswith('tek'):
        value = 2.3 if len(w) <= 3 else 0.3
    elif w in ('tec', 'tele'):
        value = 0.9
    elif w.startswith('telesc'):
        value = 0.7
    elif w == 'tell':
        value = 0.4
    elif w == 'talk':
        value = 1.1
    elif w == 'talks':
        value = 0.55
    elif w.startswith('talk'):
        value = 0.2
    elif w.endswith('tel'):
        value = 0.7
    elif w == 'intellig':
        value = 1.6

