        if s == 'ech':
            value = 8.5
        elif re.fullmatch(r'e[clk]', s):
            value = 4.5
        elif re.fullmatch(r'e[ck]t', s):
            value = 2.8
        elif re.fullmatch(r'el[lsn]', s):
            value = 3.0
        elif s.startswith('el'):
            value = 1.4
    if p.endswith('te') and not word_start:
        if s == 'ch':
            value = 10.0
        elif s.startswith('ch'):
            value = 4.0 if len(s) <= 3 else 0.5
        elif s == 'ck':
            value = 1.5
        elif s in ('c', 'k'):
            value = 4.5
        elif s.startswith('l'):
            value = 3.0 if len(s) <= 4 else 0.5
    if p.endswith('tel') and s.startswith('l') and not word_start:
        value = 3.2

    if re.match(r'\s*т[еэ][лхкч]', s):
        value = 2.8 if len(w) <= 3 else 0.3
    if p.endswith('т') and re.match(r'[еэ][лхкч]', s):
