        value = 4.5
    if p.endswith('τ') and s.startswith('η'):
        value = 1.6
    if p.endswith(('τε', 'τη')) and s.startswith(('χ', 'λ')):
        value = 6.5 if s.startswith('χ') else 2.0
    if p.endswith('テ') and s in ('ク', 'ル'):
        value = 6.0 if s == 'ク' else 3.2
    if p.endswith('ت') and s.startswith('يل'):
        value = 1.5
    if w == '科技':
        value = 1.0
    if s == '··':
        value = 1.54
    return (doc, (p + s)[-12:]), value

"""Approximate a Slavic sibilant-spelling signal.

The strongest cue is Cyrillic щ, especially short or byte-split tokens.
Longer and participial-looking endings weaken it. Smaller cues are ш/ж, clusters
such as жд, шт, szcz and št, and a brief same-word continuation after щ.
There is also a small GitHub-domain cue and a document-initial offset.
Only the last few characters and an unfinished UTF-8 character are kept.
"""
import codecs
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    _, pending, tail, last = (doc, b"", "", "") if start else carry
    raw = prefix.token_bytes[-1]
    data = pending + raw
    text, used = codecs.utf_8_decode(data, "replace", False)
    pending = data[used:]
    s, p = text.lower(), tail.lower()
    word = s.strip()
    joined = p[-3:] + s
    boundary = len(p[-3:])

    def new(pattern):
        i = joined.rfind(pattern)
        return i >= 0 and i + len(pattern) > boundary

    value = 0.002 - 0.206 * start
    if any("CYRILLIC" in unicodedata.name(ch, "") for ch in s):
        value -= 0.021
    if "ш" in s:
        value += 0.411
    if "ж" in s:
        value += 0.338
        if "жб" in s:
            value -= 0.362

    q = s.find("щ")
    if q >= 0:
        after = len(s) - q - 1
        before = q - (len(s) - len(s.lstrip()))
        if word == "щ":
            strength = 9.927
        elif after == 0:
            strength = 6.382
        else:
            suffix_strengths = (5.3, 3.2, 1.8)
            strength = suffix_strengths[min(after, 3) - 1]
        if before == 0 and word != "щ":
            strength += 1.600
        if before >= 5:
            strength -= 2.278
        if any(x in s for x in ("ущ", "ющ", "ящ")):
            strength -= 2.15
        if "ующ" in s:
            strength -= 3.465
        if raw and 128 <= raw[0] < 192:
            strength += 7.910
        if word == "щ" and p.endswith(("а", "я")):
            strength -= 2.520
        if p.endswith("щ"):
            strength += 1.958
        if "Щ" in text:
            strength += 3.056
        value += max(0., strength)

    if s[:1].isalpha():
        if "щ" in last.lower():
            value += 1.752
            if last.lower().strip() == "щ":
                value += 1.676
        if p.endswith(("ш", "ж")):
            value += 0.427

    # Sibilant clusters can be completed across token boundaries.
    if p.endswith("ж") and s.startswith("д"):
        value += 2.985
        if word == "д":
            value += 1.681
        if p.endswith("еж"):
            value -= 0.628
        if p.endswith(("рж", "нж")):
            value -= 3.233
    if p.endswith("ж") and s.startswith("б"):
        value += 1.553
    if p.endswith("ш") and s.startswith("т"):
        value += 5.607
        if s.startswith("то"):
            value -= 1.406
    for pattern, weight in (
        ("чш", 1.617),
        ("ьш", 1.446),
        ("кж", 1.178),
        ("szt", 1.736),
        ("sht", 1.170),
        ("št", 3.878),
        ("šť", 3.878),
    ):
        if new(pattern):
            value += weight
    if new("szcz"):
        value += 4.158
        if p.endswith("sz") and s.startswith("cz"):
            value += 7.034
    else:
        if new("szc"):
            value += 13.107
        if new("sz"):
            value += 0.256
    if "š" in s:
        value += 0.377
    if s.startswith("ě") and p.endswith(("t", "ť", "p", "d", "n")):
        value += 0.438
        if p.endswith(("št", "šť")):
            value += 7.710
    if s == ".com" and p.endswith("github"):
        value += 1.438
    return (doc, pending, (tail + text)[-12:], text), float(value)

"""Approximate a lexical potential/potency feature, including word fragments.

The main response is negative on 'potential', its cognates and their shared
pot-/poten- beginnings.  A short text tail joins split words.  Noun-like
contexts (full, chemical, etc.) strengthen 'potential'; 'potentially' is weaker.
Chinese latent/potential characters and compounds are handled separately,
with weaker responses to position, force and electrical-battery characters.
There is also a small response on 'of' after potential, power, or point.
Other positions get zero; the short text state resets at document boundaries.
"""
import re
import regex
from anyascii import anyascii

READS = ()
WORD = regex.compile(r"[\p{Latin}\p{Cyrillic}]+$")
DETERMINERS = {'a', 'an', 'the', 'my', 'your', 'our', 'his', 'her', 'their', 'its'}
PHYSICS_CUES = {
    'chemical', 'electrical', 'electrostatic', 'gravitational',
    'scalar', 'electrode', 'formal',
}


def word_at_end(text):
    m = WORD.search(text)
    return anyascii(m.group()).lower() if m else ''


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    tail = '' if reset else carry[1]
    s = prefix.token_strings[-1]
    old = word_at_end(tail)
    text = (tail + s)[-100:]
    word = word_at_end(text)
    token = s.strip().lower()
    ascii_token = anyascii(token)
    value = 0.0
    recent_bytes = prefix.token_bytes[-1:] if reset else prefix.token_bytes[-2:]
    partial_han = b''.join(recent_bytes).endswith(b'\xe6\xbd')

    if partial_han:
        value = -7.5  # Incomplete UTF-8 prefix shared by 潜 and 潛.
    elif token in ('潜', '潛'):
        value = -12.5 if token == '潛' or not tail.endswith(('反', '对')) else -7.0
    elif token.startswith(('潜', '潛')):
        value = -0.8 if '艇' in token else -4.7
    elif token in ('势', '勢'):
        value = -2.2
    elif token == '位':
        value = -4.8 if tail.endswith('点') else -0.9
    elif token == '池' and tail.endswith(('電', '电')):
        value = -2.0
    elif token == '能' and tail.endswith(('潜', '潛')):
        value = -5.0
    elif word.startswith('poten') and s[-1:].isalpha():
        root = word.replace('potents', 'potenc')
        if root == 'potentially':
            value = -4.2
        elif root == 'potentials':
            value = -10.3
        elif root == 'potential':
            value = -6.8
            words = re.findall(r'[^\W\d_]+', tail.lower())
            prev = words[-1] if words else ''
            if prev in {'full', 'fullest'}:
                value -= 5.5
            elif prev in PHYSICS_CUES:
                value -= 3.0
            elif prev in {'innate', 'true', 'great', 'vast'}:
                value -= 2.0
            elif prev in DETERMINERS - {'a', 'an', 'the'}:
                value -= 1.7
            elif prev == 'the':
                value -= 1.0
            elif prev in {'a', 'an', 'any'}:
                value += 1.3
            if not tail:
                value = -10.7
        elif root in ('potent', 'potency'):
            value = -1.5
        elif root.endswith(('encia', 'encias', 'enza', 'ente', 'enti', 'iar')):
            value = -1.0
        elif root == 'potenc':
            value = -4.2
        elif len(token) == 1:
            value = -1.5
        elif root.endswith(('cial', 'zial', 'tiel')):
            value = -9.0
        elif len(root) <= 9:
            value = -7.8
        elif old in ('poten', 'potent'):
            value = -4.0
    elif token in ('pot', 'пот'):
        if old in DETERMINERS:
            value = -1.0
        elif s.strip()[:1].isupper() or not s[:1].isspace():
            value = -2.2
        else:
            value = -3.8
    elif word.endswith('potent') and old.endswith('p'):
        value = -4.3
    elif (len(ascii_token) <= 3 and 'pot' in word
          and 'pot' not in old and 'pot' not in ascii_token):
        value = -4.5 if word.startswith('pot') else -2.5
        if word.startswith('hypot'):
            value = -0.8
    elif token.strip('-') == 'of':
        if old.endswith('potential'):
            value = -2.8
        elif old in ('point', 'power'):
            value = -1.8
    return (doc, text), value

programs.haiku:
"""Stem of the word "potential" (and its relatives), in English and other languages.

The component goes negative on the token or tokens that spell the word "potential":
- strongest on the whole word (" potential", "Potential", "potentials"): about -8;
- weaker on its relatives ("potent", "potency", "potentially", "potencia"): about -3.5;
- weaker still on beginnings of the word, "pot", " pot", " Pot", Russian "пот"/"потен": about -2.7;
- on the Chinese words for potential or latent force (潜力, 潜, 势, 勢): -2.5 to -6;
- and on " of" right after a potential word ("the potential of"): about -2.5.

The word is read from the text so far: the run of letters ending at the current token,
lowercased, so a word split over several tokens still counts. Everything else is 0,
except one oddity seen in a training row made only of the token "··" (a run of middle
dots), where the component sits at +1.56. That row is one example, not a general rule.
"""
import re

READS = ()

# The whole word, in several languages: the strongest response.
FULL = {"potential", "potentials", "potencial", "potenziale", "potentiel", "потенциал"}
# Relatives of the stem: a weaker response.
RELATIVES = {"potent", "potentially", "potency", "potencia", "potens"}
# Chinese words for potential / latent force, matched on the token itself.
CHINESE = {"潜力": -6.0, "潜": -6.0, "潛": -6.0, "势": -2.5, "勢": -2.5}
# Filler token seen in one training row.
FILLER = {"··": 1.56}

LETTERS = re.compile(r"[^\W\d_]+$")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in FILLER:
        return None, FILLER[token]
    if token in CHINESE:
        return None, CHINESE[token]
    match = LETTERS.search(prefix.text_prefixes[-1][-40:])
    word = match.group(0).lower() if match else ""
    if word in FULL:
        return None, -8.0
    if word in RELATIVES:
        return None, -3.5
    if len(word) >= 3 and any(full.startswith(word) for full in FULL):
        return None, -2.7
    if token == " of" and len(prefix.token_strings) > 1:
        before = LETTERS.search(prefix.text_prefixes[-2][-40:])
        if before and before.group(0).lower() in FULL | RELATIVES:
            return None, -2.5
    return None, 0.0

programs.sol:
"""Approximate the negative response to nominal English 'one'/'ones'.

Dictionary adjectives, ordinals and definite modifiers make the response
strong; bare numerical uses are nearly quiet. 'The only one' and 'loved ones'
receive separate treatment. Copulas after lowercase "following" give positive
values. Title-case forms are generally weaker. Only a bounded tail of text is
kept, reset at document boundaries.
"""
import re
import inflect
import wordnet

READS = ()
PREPOSITIONS = set('of to in on at by for from with without into onto over '
                   'under about after before through between within per as '
                   'than like near out up off around'.split())
POSSESSIVES = set('my your his her its our their'.split())
DETERMINERS = POSSESSIVES | set('the a an this that these those each another'.split())
_numbers = inflect.engine()
CARDINALS = {_numbers.number_to_words(n) for n in range(21)}
CARDINALS |= {_numbers.number_to_words(10**n) for n in (2, 3, 6, 9)}
FUNCTIONS = PREPOSITIONS | CARDINALS | set('number plus minus just even '
    'still then all both ago down'.split())


def one_strength(text, plural):
    words = re.findall('[a-z]+', text.lower())[-5:]
    p = words[-1] if words else ''
    q = words[-2] if len(words) > 1 else ''
    if not re.search('[A-Za-z]$', text):
        return -1.5 if plural else 0.15
    if re.search(r'\b\d+(st|nd|rd|th)$', text):
        return -9.5 if plural else -11.0
    if p == 'the':
        return -5.2 if plural else (-3.9 if q == 'on' else -7.0)
    if p in {'a', 'an'} | POSSESSIVES or text.endswith("'s"):
        return -2.0 if plural else -2.2
    if p in ('this', 'these', 'those'):
        return -6.5 if plural else -7.5
    if p == 'that':
        return -2.0 if plural else -0.5
    if p == 'which':
        return -3.0 if q in PREPOSITIONS else (-7.0 if plural else -9.5)
    if p in ('each', 'another'):
        return -7.0 if plural else -9.0
    if p in ('only', 'least'):
        if q == 'the':
            return -8.0 if plural else -10.0
        return -0.8 if plural else 0.1
    if p == 'no':
        return -0.6
    if p in ('every', 'either'):
        return -3.3
    if p in ('any', 'some', 'more', 'less', 'loved'):
        return -1.3
    if p in FUNCTIONS or len(p) < 2:
        return -0.8 if plural else 0.1

    pos = wordnet.parts_of_speech(p)
    modified = q in DETERMINERS or q in ('more', 'most', 'very', 'so', 'too')
    modified |= q.endswith('ly') and any(w in DETERMINERS for w in words[-4:-2])
    modified |= bool(re.search(r'\w+-[A-Za-z]+$', text))
    participle = p.endswith(('ed', 'ing', 'en')) or p in ('found', 'cut', 'said', 'made')
    suffix = p.endswith(('ical', 'al', 'ous', 'ive', 'ful', 'less', 'able', 'ible'))
    adjective = ('adjective' in pos or wordnet.is_a(p, 'color') or
                 (suffix and len(p) > 5 and (modified or plural)) or
                 ('verb' in pos and participle and modified))
    if adjective:
        if p.endswith('est') or p in ('first', 'second', 'third', 'fourth',
                                      'fifth', 'sixth', 'best', 'last'):
            return -9.5 if plural else -11.0
        if q == 'most':
            return -11.0 if plural else -14.0
        if 'verb' in pos and not modified and not plural:
            return 0.0
        if modified:
            return -8.5 if plural else -10.4
        return -7.0
    return -0.8 if plural else 0.1


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = 0.0
    if token in (' one', ' ones', ' One', ' Ones'):
        value = one_strength(text, token.lower() == ' ones')
        if token[1].isupper():
            value *= 0.65
        if not text:
            value = -2.6
    elif token in (' is', ' are') and text.endswith(' following'):
        value = 3.6 if token == ' is' else 2.4
    # Rules cannot resolve every grammatical reading: temper their strength.
    return (doc, (text + token)[-160:]), 0.9 * value

"""A sparse detector of title labels, formatting and damaged mathematical text.

The large positive response is the colon of a document-opening 'Title:'.
Negative responses cover dot leaders and several characteristic encoding/font
substitutions: Coptic-looking math signs, control-picture byte fragments,
accented capitals used as operators, and Thai/Cyrillic intrusions in Latin text.
Most ordinary text is assigned a small near-zero value. Content-specific
first-token responses are deliberately not memorized.
"""
import unicodedata
import regex

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, history, previous = 0, b'', b''
        first = prefix.token_bytes[-1]
    else:
        _, position, history, previous, first = carry
    raw = prefix.token_bytes[-1]
    token = raw.decode('utf-8', 'replace')
    word = token.strip()
    before = history.decode('utf-8', 'replace')
    joined = (history[-4:] + raw).decode('utf-8', 'replace')
    last = joined[-1:]
    name = unicodedata.name(last, '') if last else ''
    value = -0.001

    if position == 0 and word == 'Title':
        value = 0.85
    elif position == 1 and previous == b'Title' and raw == b':':
        value = 11.72
    elif word == '··':
        value = (-0.58 if first == raw
                 else -0.10 if previous == raw else 0.0)
    elif word == '<|im_end|>':
        value = -0.20
    elif word == '<tool_call>':
        value = -0.21
    elif word == '</tool_response>':
        value = 0.136
    elif word == '</think>':
        value = 0.088
    elif raw == b'\xcf':  # Unmerged leading byte of uncommon Greek/Coptic.
        value = -3.0
    elif 'COPTIC' in name and any(b >= 128 for b in raw):
        value = -2.5 if len(raw.strip()) == 1 and position > 1 else -0.4
    elif name == 'LATIN SMALL LETTER ETH' and len(raw) == 1 and position > 1:
        value = -1.5  # Split glyph used as an opening parenthesis in PDF text.
    elif word == '¼' and regex.search(r'\b[A-Za-z]\s*$', before):
        value = -0.8  # Quarter mark in the position of an equals sign.
    elif name == 'GREEK LETTER YOT':
        value = -4.5 if len(raw) == 1 else -1.6
    elif (history + raw).endswith(b'\xe2\x90'):
        # UTF-8 prefix shared by Unicode's control-picture symbols.
        value = -3.1 if raw == b'\x90' else -1.1
    elif name == 'UPWARDS ARROW FROM BAR' and len(raw.strip()) == 1:
        value = -2.0
    elif name == 'BENZENE RING':
        value = -1.1
    elif raw == b'\xe0\xb9' and any('\x80' <= c <= '\x9f' for c in before):
        value = -1.0  # Incomplete Thai glyph in already-damaged text.
    elif len(word) == 1 and regex.fullmatch(r'\p{Script=Cyrillic}', word):
        latin = sum(c.isascii() and c.isalpha() for c in before[-80:])
        cyrillic = len(regex.findall(r'\p{Script=Cyrillic}', before[-80:]))
        if latin > 15 and cyrillic < 4:
            # Cyrillic pe is also a common misdecoding of a ligature's lead byte.
            value = -2.0 if word == 'п' else -0.3
    elif word in {'โ', 'ย', 'ฮ', 'ฉ', 'จ'}:
        # These Thai glyphs also occur when UTF-8 is decoded as Windows-874.
        latin = sum(c.isascii() and c.isalpha() for c in before)
        thai = len(regex.findall(r'\p{Script=Thai}', before[-40:]))
        controls = any('\x80' <= c <= '\x9f' for c in before)
        if controls or (latin > 8 and thai < 4):
            value = -3.0 if word in {'โ', 'ย'} else -1.8
            if word == 'ฉ' and before.endswith(('ร', 'ย')):
                value = -3.5  # Misdecoded UTF-8 accented letter or copyright sign.
    elif word == 'À':
        # In prose this often starts a French sentence; in formulas it is
        # a corrupted minus sign, particularly before a unit's exponent.
        sentence_start = not before.strip() or before.rstrip(' \t').endswith(
            ('.', '\n', '"', '“', '«')
        )
        french = regex.search(
            r'\b(le|la|les|des|du|dans|pour|que|qui)\b', before.lower()
        )
        word_interior = not raw.startswith(b' ') and previous[-1:].isupper()
        accents = any(
            c not in 'ÀÁÃÂ' and unicodedata.name(c, '').startswith('LATIN ')
            and ' WITH ' in unicodedata.name(c, '') for c in before if ord(c) > 127
        )
        prose = sentence_start or french or word_interior or accents
        value = 0.07 if prose else -1.8
    elif word == 'Á' and (
        (raw == 'Á'.encode() and previous[-1:].islower())
        or previous.strip() == 'À'.encode()
    ):
        value = -1.8  # Corrupted multiplication dot between unit names.
    elif word == 'Ã':
        variable = previous.startswith(b' ') and previous.strip().isalpha()
        variable = (variable and len(previous.strip()) == 1
                    and raw.startswith(b' '))
        value = -1.9 if variable else -0.20

    return (doc, position + 1, (history + raw)[-256:], raw, first), value

programs.haiku:
"""Layer 1 MLP down_proj component 4667: sparse, token-triggered.

Mostly silent. Three readable triggers:
- the colon of a document-opening "Title:" label (a "Title" token straight after
  <|endoftext|>, then ":"): a large positive spike;
- a few Thai letters and repeated middle dots, which push it negative.
Everywhere else it predicts 0.
"""

READS = ()

TITLE_COLON = 11.7
THAI_LETTERS = {"ฉ": -1.5, "จ": -0.9, "ฮ": -2.1, "โ": -3.0}
OTHER_TOKENS = {"··": -0.6, "<|im_end|>": -0.2, "<tool_call>": -0.2}


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    current = tokens[-1]
    if current == ":" and len(tokens) >= 3 and tokens[-2] == "Title":
        if tokens[-3] == "<|endoftext|>":
            return carry, TITLE_COLON
    if current in THAI_LETTERS:
        return carry, THAI_LETTERS[current]
    return carry, OTHER_TOKENS.get(current, 0.0)

programs.sol:
"""Approximate a signed spelling response, mostly to 'if'.

Conditional 'if' gets negative values, stronger in code and identifiers than
in clause openings or indirect questions. 'iff' and some short IF fragments
also respond. A separate positive branch recognizes short hi/hik/hir/hid/hiw
fragments and short-i vowel marks. Everything else is zero. These rules omit
many idiosyncratic responses; they are not a full semantic conditional parser.
"""
import re
import unicodedata

READS = ()
INQUIRY = {
    'see', 'know', 'wonder', 'wondering', 'wonders', 'sure', 'unsure',
    'determine', 'determining', 'ask', 'asks', 'asked', 'asking',
    'check', 'checks', 'checking', 'tell', 'understand',
}
CONNECTIVES = {
    'even', 'but', 'so', 'that', 'as', 'because', 'especially',
    'particularly', 'maybe', 'then',
}


def response(token, before):
    if not token.isascii():
        names = [unicodedata.name(c, '') for c in token]
        if any(n.endswith('VOWEL SIGN I') or n == 'THAI CHARACTER SARA I'
               for n in names):
            return 3.0 if '\ufffd' in token else 0.2

    # Small HI spelling fragments, possibly split between adjacent tokens.
    t = token.lower()
    if re.fullmatch(r'hi(?:[kdrw][aeiou]?)?', t):
        lead = before[-1:].lower() + 'hi'
    elif (re.fullmatch(r'i(?:[kdrw][aeiou]?)?', t)
          and before.lower().endswith('h')):
        lead = before[-2:].lower() + 'i'
    else:
        lead = None
    if lead is not None:
        if lead == 'dhi':
            return 3.0
        if lead == 'chi':
            return 0.25
        return 1.0 if before[-1:].isalpha() else 0.1

    s = token.strip()
    lower = s.lower()
    if lower == 'iff':
        return -3.6 if token[:1].isspace() else -0.4
    if s == 'FF' and before.endswith('I'):
        return -2.8
    if re.fullmatch(r'[_(/-]+[iI][fF]', s):
        return -3.2 if s.startswith('_') else -1.55
    if s.isupper() and s.startswith('IF') and len(s) == 3:
        return -3.3 if before.endswith('I') else 0.0
    if lower not in {'if', 'ify'}:
        return 0.0

    line = re.split(r'\n|\\n', before)[-1]
    words = re.findall(r'[A-Za-z]+', before)
    word = words[-1] if words else ''
    code = bool(re.search(r'[=;{}\[\]]|\\[nt]|`', before[-180:]))
    if lower == 'ify':
        return -1.2 if code else -0.6
    if s == 'IF':
        sql = r'\b(?:CREATE|DROP)(?:\s+TEMPORARY)?\s+(?:TABLE|DATABASE)\s*$'
        if re.search(sql, before, re.I):
            return -10.0
        if word.upper() in {'COUNT', 'SUM', 'COUNTIFS', 'SUMIFS'}:
            return -6.5
        if before.endswith(('_', '_I')):
            return -3.3
        if not token[:1].isspace() and word.isupper() and len(word) <= 3:
            return -0.5
        return -1.15
    if s == 'If':
        if not before:
            return 0.34
        if not token[:1].isspace() and before[-1:].isalnum():
            return -2.8
        return -0.3 if code else -0.07
    if word.lower() in {'what', 'again'}:
        return -1.85
    if re.fullmatch(r'\s*\d+[ \t]+', line):
        return -1.2
    if '\\n' in before[-80:] and re.fullmatch(r'(?:\s|\\t)*', line):
        return -1.5
    if token.startswith('\t') or (before and re.fullmatch(r'\s*', line)):
        return -0.9
    if before.rstrip().endswith(','):
        return -0.08
    if word.lower() in INQUIRY and not re.search(r'#|//', line):
        return -0.12
    if word.lower() in CONNECTIVES:
        return 0.0
    if code:
        return -0.9
    return -0.33 if word.lower() in {'and', 'or'} else -0.41


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, (before + token)[-300:]), response(token, before)

"""A lexical detector centered on contribution words and the 'trib' stem.

Contribution words give large negative responses, especially across token
splits (CONTR + IBUT + ING). Related attribution, distribution, tribe and
tribute spellings are weaker, as are 'ib'/'rib'/'bib' fragments. Cyrillic is
transliterated; Chinese/Japanese contribution and submission words have their
own rules, including a split UTF-8 character. A few following prepositions
retain a response. State resets at document boundaries. This approximates
spelling and local phrases, not the sentence's meaning; most tokens get zero.
"""
import regex as re
from anyascii import anyascii

READS = ()


def response(text, previous):
    if re.search(r"\p{Script=Cyrillic}", text):
        text = anyascii(text)
    lower = text.lower()
    piece = lower.strip()
    joined = previous + lower if lower[:1].isascii() and lower[:1].isalpha() else lower
    word = re.search(r'[a-z]+$', joined)
    word = word[0] if word else ''
    value = 0.0

    if 'contrib' in joined:
        split = 'contrib' not in lower
        noun = 'tion' in joined or 'tor' in joined
        if split:
            if previous.endswith(('con', 'contr')):
                value = -6.5 if noun else -12.0
            elif previous.endswith('contribut'):
                value = -7.0 if noun else -9.4
            elif previous.endswith('contrib'):
                value = -5.0 if noun else -4.8
                if piece.startswith('ut') and not noun:
                    value = -10.0
                if piece == 'uted':
                    value = -13.0
            # Later pieces of a long word no longer contain the root.
        else:
            value = -5.0 if noun else -6.1
            if piece.endswith('tions'):
                value += 0.5
            if piece == 'contrib':
                value = -6.6
            if text.strip().isupper():
                value = -4.8
            elif not text.startswith(' ') and piece.startswith('contrib'):
                value -= 1.4
    elif 'trib' in joined:
        if 'attrib' in joined or 'atrib' in joined:
            if 'trib' not in lower:
                if previous.endswith(('attrib', 'atrib')):
                    value = -3.7
                elif previous.endswith('tri'):
                    value = -6.0
            elif piece.endswith('trib'):
                value = -2.7
            else:
                value = -0.7
        elif 'distrib' in joined:
            if 'trib' in lower:
                value = -0.4
            elif previous.endswith('distrib'):
                value = -3.0
            elif previous.endswith('tri'):
                value = -10.0
        elif 'trib' not in lower:
            if 'trib' not in previous:
                value = -9.0
            elif previous.endswith('trib'):
                value = -1.8
                if piece.startswith('ut'):
                    value = -9.0
                elif piece.startswith('un'):
                    value = -7.0
                elif piece in ('e', 'es'):
                    value = -4.2
            elif previous.endswith('tribut'):
                value = -5.0
        elif piece in ('trib', 'tribute'):
            value = -6.0
            if not text.startswith(' '):
                value -= 3.0
        elif piece.startswith('tribal') or piece.startswith('tribe'):
            value = -1.5
        elif piece.startswith('tribun'):
            value = -3.0
        elif piece.startswith('tribut'):
            value = -5.0
    elif word.endswith('contr') and piece == 'tr':
        value = -4.0
    elif piece in ('ib', 'rib', 'bib'):
        value = -1.2 if piece == 'ib' else -2.0

    if piece == 'by' and previous.endswith('contributed'):
        value = -4.0
    elif piece == 'of' and previous.endswith(('contribution', 'contributions')):
        value = -2.0
    elif piece == 'to' and 'contrib' in previous:
        value = 0.25

    if any(w in text for w in ('贡献', '貢献', '貢獻')):
        value = -4.8
    elif '投稿' in text:
        value = -4.0
    elif text in ('贡', '貢'):
        value = -8.0
    elif text in ('献', '獻'):
        value = -3.5
    elif text == '稿':
        value = -1.5
    return word[-64:], value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same_doc = carry is not None and carry[0] == doc
    previous = carry[1] if same_doc else ''
    tail = carry[2] if same_doc else b''
    raw = prefix.token_strings[-1]
    joined_bytes = tail + prefix.token_bytes[-1]
    completed = joined_bytes.decode('utf-8', errors='ignore')
    word, value = response(raw, previous)
    if raw == '献' and completed.endswith('貢献'):
        value = -7.5
    elif '貢' in completed and '貢' not in raw and '\ufffd' in raw:
        value = -15.0
    return (doc, word, joined_bytes[-6:]), value

"""Surface forms of multiplicity: 多, poly- and multi-.

The response is strongest to the bare roots and to roots completed across
subword boundaries. Fused, familiar words (e.g. 'multiple', 'polynomial',
'很多') are weaker. Carry only the current word and previous token, resetting
at document boundaries. Negative rules mark continuations that resolve an
ambiguous root away from the strong response. Everything else is zero;
small context-dependent responses are omitted. Values are training estimates.
"""
import re
import regex

READS = ()


def response(s, before, previous):
    t = s.strip()
    low = t.lower()
    joined = before + low if t and s[0].isalpha() else low

    if t == '多':
        return 4.2
    if t in ('有多', '得多', '或多'):
        return 7.7
    if t.endswith('多么'):
        return 5.5
    if '多' in t:
        if regex.search(r'\p{Hiragana}|\p{Katakana}', t):
            return 0.3
        if any(w in t for w in ('更多', '多数', '多样', '差不多')):
            return 0.0
        if '很多' in t:
            return 0.5
        if '许多' in t:
            return 1.0
        if '多少' in t:
            return 0.7
        if t in ('多次', '太多'):
            return 1.0
        if t in ('多个', '多种'):
            return 1.7
        if t.startswith('多年'):
            return 2.1
        if len(t) == 2:
            return 2.6
        return 0.8
    if previous == '多':
        if t == '边':
            return 6.8
        if t == '点':
            return 4.5
        if len(t) == 1 and t in '个种項项位家人模':
            return 1.2

    # Familiar fused words are weaker than their bare combining forms.
    if 'polynomial' in joined or 'monopoly' in joined:
        return 0.45 if 'polynomial' in joined else 0.0
    if 'empoly' in joined:  # misspelling of employee, not the poly- prefix
        return 0.0
    m = low.lstrip('._-/(')
    if m.startswith('poly'):
        if m in ('polym', 'polys'):
            return 3.6
        if m.startswith(('polygon', 'polyester')):
            return 1.2
        return 2.0
    if m.startswith('mult'):
        if m == 'multip' or m.startswith(('multiple', 'multipli', 'multiply')):
            return 0.15
        if m == 'mult':
            return 1.4
        if m == 'multiline':
            return 5.0
        if m == 'multim':
            return 4.0
        return 2.3

    # The same roots completed across token boundaries.
    if 'poly' in joined and 'poly' not in before:
        if before.endswith('pol'):
            if low.startswith(('yp', 'ycl', 'yn')):
                return 3.5
            return 8.0
        return 3.0 if before.endswith('cop') else 5.2
    if (before.endswith('m') and not before.endswith('sim')
            and 'mult' not in before and 'mult' not in low
            and 'mult' in joined):
        if joined.endswith('mult'):
            return 6.5
        if (any(w in joined for w in ('multiple', 'multipli', 'multiply'))
                or joined.endswith('multip')):
            return 0.5
        return 4.5
    if before.endswith('mult') and low.startswith('i'):
        if low.startswith('iline'):
            return 6.0
        return 4.0 if len(low) <= 2 else 1.0
    # An ambiguous pol- stem followed by something other than y is counterevidence.
    if before.endswith('pol') and s and s[0].isalpha() and not low.startswith('y'):
        return -0.8
    if before.endswith('poly') and s and s[0].isalpha():
        if low.startswith('hed'):
            return 4.9
        if low.startswith('line'):
            return 7.5
        return 1.0
    if before.endswith('polym') and low in ('er', 'ers'):
        return 2.4
    if before.endswith('polype') and low.startswith('ptide'):
        return 2.9
    if before.endswith('multim') and low == 'odal':
        return 4.0
    if before.endswith('multi'):
        if low.lstrip('-').startswith('player'):
            return 6.0
        if low.startswith('pl'):
            return 0.1
        if s and s[0].isalpha():
            return 1.0
    if before.endswith('multip') and low == 'lex':
        return -2.7
    if low == 'of' and previous in ('plenty', 'plurality'):
        return -1.4
    if low == 'đa':  # Vietnamese multi-
        return 2.6
    if low == 'nhiều':  # Vietnamese many
        return 0.6
    if t == '다':
        return 2.2 if s.startswith(' ') else 1.3
    if before.endswith('много') and low == 'е':
        return -4.5
    if low in ('мног', 'много'):
        return 1.6
    if before.endswith('м') and low.startswith('ульт'):
        return 4.5
    if joined.endswith('много') and s and s[0].isalpha():
        return 7.0 if before == 'м' else 1.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before, previous = ('', '') if carry is None or carry[0] != doc else carry[1:]
    s = prefix.token_strings[-1]
    value = response(s, before, previous)
    # Keep only the last alphabetic word, not the preceding document.
    text = before + s.lower() if s and s[0].isalpha() else s.lower()
    match = re.search(r'[^\W\d_]+$', text)
    word = match.group()[-48:] if match else ''
    return (doc, word, s.strip()), value

