"""Self / from morpheme detector for layers.1.mlp.down_proj:4671.

The component fires on the Sino-morpheme 自 ("self"; also "from / originating from" in
来自, 源自, 出自, and "each's own" in 各自, 独自) and on the same morpheme's sound-alikes
in other languages: Vietnamese tự ("self") and từ ("from") and the Sino-Vietnamese
syllables tư, tử, tứ, and Korean 자 ("self" in 자신, 자주, 자금). Everything else is near zero.
"""

READS = ()
VI_SINO_T = {"tự": 7.0, "từ": 4.5, "tư": 2.5, "tử": 2.2, "tứ": 4.0}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    tok = raw.strip()
    if tok == "自":
        value = 1.3
    elif tok == "自己":
        value = 0.7
    elif tok.endswith("自") and len(tok) >= 2:
        value = 2.0  # 来自, 源自, 各自, 独自: 'from' / 'each own'
    elif "自" in tok:
        value = 0.3
    elif tok.lower() in VI_SINO_T:
        value = VI_SINO_T[tok.lower()]
    elif tok == "자":
        value = 3.0 if raw.startswith(" ") else 0.8  # Korean 자
    else:
        value = 0.0
    return carry, value
